// SharkSight: one scan volume per checkpoint. Screens are added as the pipeline stages are rebuilt
// (classify → cluster → contextualize → elicit); each reads the shared checkpoint from useCheckpoint().
import { Navigate, Route, Routes } from "react-router-dom";
import { CheckpointProvider } from "@/state/checkpoint";
import { SweepControl } from "@/components/SweepControl";
import { AuditPanel } from "@/components/AuditPanel";
import { Scan } from "@/screens/scan/Scan";

export default function App() {
  return (
    <CheckpointProvider>
      <Routes>
        <Route path="/" element={<Scan key="volume" />} />
        <Route path="/structure" element={<Scan key="volume" mode="structure" />} />
        <Route path="/definition" element={<Scan key="volume" mode="definition" />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
      <SweepControl />
      <AuditPanel />
    </CheckpointProvider>
  );
}
// The two pages share one 3D volume: Evidence (raw sources) and Structure (what the AI made of them).
// Switching keeps the canvas mounted, so the comments fly into their clusters and back.
import { NavLink, useSearchParams } from "react-router-dom";
import { LogoMark } from "./Logo";
import "./pageswitch.css";

export function PageSwitch() {
  const [params] = useSearchParams();
  const q = params.toString() ? `?${params}` : "";
  return (
    <nav className="pageswitch" aria-label="Pages">
      <span className="brand"><LogoMark /><span className="brand-name">SharkSight</span></span>
      <NavLink to={`/${q}`} end>Evidence</NavLink>
      <NavLink to={`/structure${q}`}>Structure</NavLink>
      <NavLink to={`/definition${q}`}>Definition</NavLink>
    </nav>
  );
}
// Which top-right panel is open: the audit trail or (on Definition) the requirements. They share the corner, so
// opening one closes the other. A tiny external store, read with useSyncExternalStore.
import { useSyncExternalStore } from "react";

export type TopPanel = "audit" | "requirements" | null;

let open: TopPanel = null;
const subs = new Set<() => void>();
const subscribe = (f: () => void) => { subs.add(f); return () => { subs.delete(f); }; };

export function setTopPanel(next: TopPanel | ((cur: TopPanel) => TopPanel)) {
  const v = typeof next === "function" ? next(open) : next;
  if (v === open) return;
  open = v;
  subs.forEach((f) => f());
}
export const getTopPanel = () => open;
export const useTopPanel = () => useSyncExternalStore(subscribe, () => open);
/** open `p`, or close it when it is already open */
export const toggleTopPanel = (p: Exclude<TopPanel, null>) => setTopPanel((cur) => (cur === p ? null : p));
/* Track-while-scan: a true-black scan volume, white contacts, one blue for the sweep and the PM's marks,
   amber only for weakened / lost tracks. Numerals carry the information; words are labels, never paragraphs. */
:root {
  color-scheme: dark;

  /* ground */
  --void: #000000;
  --glass: rgba(10, 12, 15, 0.72);
  --hair: rgba(255, 255, 255, 0.09);
  --hair-2: rgba(255, 255, 255, 0.16);
  /* the frameless panel field (inspector, hover card, filter values, audit trail, dock): plain black at 86%, as the
     audit trail had it; no tint, no glow */
  --field: rgba(0, 0, 0, 0.86);

  /* ink */
  --ink: #f2f4f7;
  --ink-2: #b4bac4;
  --ink-3: #868d99;   /* ≥ 4.5:1 on black */

  /* signal */
  --sweep: #1c69d4;
  --sweep-hi: #4d94ff;
  --sweep-wash: rgba(28, 105, 212, 0.18);
  --lost: #f5a524;

  /* type */
  --font: "Mona Sans Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --t-micro: 11px;
  --t-label: 12px;
  --t-body: 14px;
  --t-read: 18px;

  /* space, shape, motion */
  --edge: 24px;
  --r: 10px;
  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --fast: 160ms;
  --med: 240ms;
  --sweep-ms: 2400ms;   /* matches the 3D sweep in Scene.tsx */
}
// Thin client for the local SharkSight API (`api/`, FastAPI). Every write carries the acting PM in X-Actor;
// the server records it in the append-only audit trail.
import { QueryClient } from "@tanstack/react-query";

const ACTOR_KEY = "successor.actor";
export const DEFAULT_ACTOR = "Atahan (PM)";

export function getActor(): string {
  try {
    return localStorage.getItem(ACTOR_KEY) || DEFAULT_ACTOR;
  } catch {
    return DEFAULT_ACTOR;
  }
}
export function setActor(name: string) {
  try {
    localStorage.setItem(ACTOR_KEY, name);
  } catch {
    /* private mode: fall back to the default actor */
  }
}

export class ApiError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

async function request<T>(method: string, path: string, body?: unknown): Promise<T> {
  let res: Response;
  try {
    res = await fetch(path, {
      method,
      headers: { "Content-Type": "application/json", "X-Actor": getActor() },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  } catch {
    throw new ApiError(0, "The local API isn't reachable. Start it with `uv run python -m api`.");
  }
  if (!res.ok) {
    let msg = `${res.status} ${res.statusText}`;
    try {
      const j = await res.json();
      if (typeof j.detail === "string") msg = j.detail;
      else if (Array.isArray(j.detail)) msg = j.detail.map((d: { msg?: string }) => d.msg).join("; ");
    } catch {
      /* keep status text */
    }
    throw new ApiError(res.status, msg);
  }
  if (res.status === 204) return undefined as T;
  return (await res.json()) as T;
}

export const api = {
  get: <T,>(path: string) => request<T>("GET", path),
  post: <T,>(path: string, body?: unknown) => request<T>("POST", path, body ?? {}),
  put: <T,>(path: string, body?: unknown) => request<T>("PUT", path, body ?? {}),
  patch: <T,>(path: string, body?: unknown) => request<T>("PATCH", path, body ?? {}),
};

export function qs(params: Record<string, string | number | boolean | null | undefined>): string {
  const u = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) if (v !== undefined && v !== null && v !== "") u.set(k, String(v));
  const s = u.toString();
  return s ? `?${s}` : "";
}

export const queryClient = new QueryClient({
  defaultOptions: { queries: { staleTime: 15_000, refetchOnWindowFocus: false, retry: 1 } },
});

/** Everything a decision can change; refetched after every write. */
export function invalidateAll() {
  return queryClient.invalidateQueries();
}

/** Log a "view" access event once per browser session per requirement (StrictMode mounts effects twice in dev). */
const viewed = new Set<string>();
export function logView(reqId: string) {
  if (viewed.has(reqId)) return;
  viewed.add(reqId);
  api.post("/api/access", { action: "view", entity_type: "requirement", entity_id: reqId }).catch(() => viewed.delete(reqId));
}
// API shapes for the requirement-definition layer (D-048, api/routers/definition.py; contract in
// foundation/documents/requirement-definition.md → "API").
import type { CheckpointId, TrackState } from "./types";
import type { Orientation, ZoneDef } from "@/three/frame";

export type LineName = "1 Series" | "5 Series" | "7 Series";
export type Basis = "cited" | "projected" | "assumption" | "gap";
export type Rung = "baseline" | "threshold" | "target" | "stretch";
export type ChoosableRung = Exclude<Rung, "baseline">;
export type Relation = "conflicts" | "competes_for" | "enables" | "synergy";
export type Via = "energy" | "mass" | "thermal" | "package" | "attention" | "aero" | "acoustic" | "compute";
/** Track state of a requirement / link; the spec track reports a moved recommended target as "changed". */
export type DefState = TrackState | "changed";

export interface Level {
  value: number | null;
  text: string;
  basis: Basis;
  source_ids: string[];
  note: string;
}

export interface Choice { level: ChoosableRung; rationale: string; actor: string; at: string }

export interface LadderRow {
  line: LineName | string;
  market: string;
  baseline: Level | null;
  threshold: Level;
  target: Level;
  stretch: Level | null;
  recommended: ChoosableRung;
  rationale: string;
  choice?: Choice | null;
}

export interface Metric {
  name: string;
  unit: string;
  direction: "higher" | "lower" | "binary";
  method?: string | null;
  conditions?: string | null;
}

export interface Acceptance { criterion: string; condition: string; pass: string }

export interface Requirement {
  key: string;
  version: number;
  area_key: string;
  area_title: string;
  title: string;
  statement: string;
  domain: string;
  aspects: string[];
  zones: string[];
  lines: string[];
  markets: string[];
  decision_type: string | null;
  today_status: string | null;
  horizon: string | null;
  horizon_year: number | null;
  kano: string | null;
  state: DefState | null;
  change_note: string | null;
  metric: Metric | null;
  acceptance: Acceptance[];
  ladder: LadderRow[];
  gaps: string[];
  assumptions: string[];
  evidence_count: number;
}

export interface LinkReview { verdict: "confirmed" | "removed" | "added"; actor: string; rationale: string; at: string }

export interface DefLink {
  id: string | number;
  a: string;
  b: string;
  relation: Relation;
  via: Via | string;
  strength: 1 | 2 | 3 | number;
  direction: "a_to_b" | "b_to_a" | "mutual";
  rationale: string;
  state: DefState | null;
  review: LinkReview | null;
}

export interface Bundle { id: string; keys: string[]; reason: string }

export interface RunInfo { id: number; finished_at: string | null; stats: Record<string, unknown> }

export interface ModelInfo { url: string | null; orientation: Orientation; attribution?: string | null; stand_in?: string | null }

export interface DefinitionPayload {
  checkpoint: CheckpointId;
  ready: boolean;
  runs: { define: RunInfo | null; specify: RunInfo | null; couple: RunInfo | null };
  domains: { key: string; label: string; aspects: string[] }[];
  resources: Record<string, string>;
  zones: Record<string, ZoneDef>;
  models: Record<string, ModelInfo>;
  requirements: Requirement[];
  links: DefLink[];
  bundles: Bundle[];
}

export interface EvidenceRef {
  id: string | number;
  kind: string;
  text: string;
  url: string | null;
  tier: string | null;
  published: string | null;
  relation: string | null;
  quote: string | null;
}

export interface RequirementDetail extends Requirement {
  evidence: EvidenceRef[];
  facts: Record<string, unknown>[];
  area: { key: string; title: string; need: string } | null;
  history: { checkpoint: string; version: number; change_note: string | null }[];
}

export interface ChoiceBody { key: string; line: string; market: string; level: ChoosableRung; rationale: string; actor: string }
export interface LinkReviewBody {
  a: string; b: string; relation: Relation; verdict: LinkReview["verdict"]; via?: string; strength?: number; rationale: string; actor: string;
}

