    return () => window.removeEventListener("keydown", onKey);
  }, [selected]);
  // switching pages drops the selection, unless the switch came from the inspector's "view in Structure" link
  const carry = useRef<{ sel: Selection; at: [number, number, number] } | null>(null);
  useEffect(() => { setSelected(carry.current); carry.current = null; setHover(null); }, [mode]);
  // page 3 (Definition): its layer mounts on the first visit and then stays, so leaving can run the car back down;
  // leaving glides the camera home to the volume as it rises again
  const [defSeen, setDefSeen] = useState(mode === "definition");
  const prevMode = useRef(mode);
  useEffect(() => {
    if (mode === "definition") setDefSeen(true);
    else if (prevMode.current === "definition") nav.current.reset++;
    prevMode.current = mode;
  }, [mode]);
  const navigate = useNavigate();
  const { search } = useLocation();
  const openInStructure = (sel: Selection, at: [number, number, number]) => { carry.current = { sel, at }; navigate(`/structure${search}`); };
  // ?area=<key> on Structure (page 3's "From area" link): select that area once the structure is loaded, then drop the param
  useEffect(() => {
    const key = mode === "structure" ? new URLSearchParams(search).get("area") : null;
    if (!key || !structure.data?.ready) return;
    const themeOf = Object.fromEntries(structure.data.themes.map((t) => [t.key, t]));
    const hit = areaLayout(structure.data, themeOf).find((x) => x.a.key === key);
    if (hit) { setStageView("areas"); setSelected({ sel: { kind: "area", key }, at: hit.at }); }
    const p = new URLSearchParams(search); p.delete("area");
    navigate(`/structure${p.size ? `?${p}` : ""}`, { replace: true });
  }, [mode, search, structure.data]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <main className="scan" data-mode={mode} aria-label={mode === "structure" ? "Structure and context at the selected checkpoint" : mode === "definition" ? "Requirement definitions on today's car at the selected checkpoint" : "Raw evidence at the selected checkpoint"}>
      <div className="scan-canvas">
        {points.data && (
          <Canvas dpr={[1, 2]} camera={{ position: HOME, fov: 40, near: 0.05, far: 60 }}
                  raycaster={{ params: { Points: { threshold: 0.018 }, Line: { threshold: 0 }, Mesh: {}, LOD: {}, Sprite: {} } }}
                  gl={{ antialias: true, alpha: false }} onCreated={({ gl }) => gl.setClearColor("#000000")}
                  onPointerMissed={() => { setSelected(null); if (mode === "definition") selectRequirement(null); }}>
            <Suspense fallback={null}>
              <Scene points={points.data} sources={sources.data} mask={sceneMask} position={position} fromPosition={fromPosition}
                     sweepId={sweepId} hoverComment={hover?.comment ?? null} locked={selected?.at ?? null} focus={selected ? layerOf(selected.sel) : null}
                     onHover={setHover} onSelect={(sel, at) => { setSelected({ sel, at }); setHover(null); }}
                     mode={mode} structure={structure.data} selected={selected?.sel ?? null} hoverKey={hoverKey}
                     onStructureHover={(h, k) => { setHover(h); setHoverKey(k ?? null); }} pulse={activity.data?.recent} filter={filter}
                     spread={spread} nav={nav} stage={stage}
                     extra={defSeen ? <DefinitionLayer active={mode === "definition"} sweepId={sweepId} spread={spread} /> : null} />
            </Suspense>
          </Canvas>
        )}
        {points.isPending && <div className="scan-state"><span className="scan-pulse" aria-hidden />Scanning</div>}
        {points.isError && <div className="scan-state error">{(points.error as Error).message}</div>}
      </div>

      {mode === "scan" ? (
        <div className="hud-tl">
          <Readout points={points.data} mask={mask} filter={filter} />
          {points.data && <FilterBar points={points.data} sources={sources.data} position={position} filter={chosen.f} order={chosen.order}
                                     onToggle={toggle} onClear={clear} />}
        </div>
      ) : mode === "structure" ? <Funnel data={structure.data} stage={stage} done={done} onStage={setStageView} onStep={step} /> : <DefinitionHud />}
      {mode !== "definition" && <Dock mode={mode} sel={selected?.sel ?? null} agent={mode === "structure" ? <AgentPanel /> : undefined} running={!!activity.data?.running} />}
      <PageSwitch />
      {points.data && mode !== "definition" && <NavPad spread={spread} onSpread={setSpread} nav={nav} />}

      {hover && !selected && <HoverCard hover={hover} points={points.data} />}
      {selected && mode !== "definition" && <Inspector sel={selected.sel} at={selected.at} mode={mode} onOpenStructure={openInStructure}
                              sales={sources.data?.sales ?? []} onClose={() => setSelected(null)} structure={structure.data}
                              cpLabel={(id) => checkpoints?.find((c) => c.id === id)?.label ?? id} />}
    </main>
  );
}

/* ------------------------------------------------------------------------------------------- glyphs */
type GlyphKind = "comment" | "study" | "option" | "sales" | "research";
const GLYPH_COLOR: Record<GlyphKind, string> = {
  comment: TYPE_COLOR.comment, study: TYPE_COLOR.study, option: TYPE_COLOR.option, sales: TYPE_COLOR.sales, research: TYPE_COLOR.research,
};
function Glyph({ kind }: { kind: GlyphKind }) {
  const c = "currentColor";
  return (
    <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden className="glyph" style={{ color: GLYPH_COLOR[kind] }}>
      {kind === "comment" && <><circle cx="4" cy="6" r="1.6" fill={c} /><circle cx="9.5" cy="4" r="1.6" fill="none" stroke={c} /><circle cx="8.5" cy="10" r="1.4" fill={c} /></>}
      {kind === "study" && <><path d="M2 8h10" stroke={c} strokeOpacity=".35" /><path d="M4 8V4M7 8v4M10 8V3" stroke={c} strokeWidth="1.3" /></>}
      {kind === "option" && <>{[2.5, 5.5, 8.5, 11.5].map((x) => <circle key={x} cx={x} cy="7" r="1" fill={c} />)}</>}
      {kind === "sales" && <><rect x="2.5" y="6" width="2" height="6" fill={c} /><rect x="6" y="3" width="2" height="9" fill={c} /><rect x="9.5" y="2.5" width="2" height="9.5" fill="none" stroke={c} /></>}
      {kind === "research" && <><path d="M1.5 9.5a6 6 0 0 1 11 0" fill="none" stroke={c} strokeDasharray="1.5 1.5" /><circle cx="7" cy="4.2" r="1.4" fill={c} /></>}
    </svg>
  );
}

/* ------------------------------------------------------------------------------------------- readout */
// One cell per colour in the scene, named and counted. The car rings carry BMW's own data plus cited public research
// in the same colour, so their cell gives both: BMW's count large, the public items beneath.
// While filters are set, every count is what they leave visible.
function Readout({ points, mask, filter }: { points: PointsPayload | undefined; mask: Uint8Array; filter: Filter | null }) {
  const { current, position } = useCheckpoint();
  const src = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity }).data;
  const s = current?.sources;
  const plus = (n: number | undefined) => (position > 1 && n ? <span className="plus">+{fmt(n)}</span> : null);
  const comments = useMemo(() => {
    if (!filter || !points) return { n: s?.feedback.visible, nu: s?.feedback.new };
    let n = 0, nu = 0;

content.content:
// Page 3 inside the shared scan canvas. Before the last stage the requirements live on a plane above the volume
// (StageLayer: areas → drafted → specified → linked); on the "car" stage today's car rises at the centre, the
// requirement definitions sit on it as pins at their car zone (colour = domain, mark shape = track state), and the
// couplings between requirements run as arcs over and through the car between their zones (solid = synergy /
// enables, dashed = conflicts / competes for, width = strength, the shared resource named at the apex).
// Selecting a requirement flies the camera to its zone (x-ray for interior zones and the battery floor).
import { memo, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import { Html, Line } from "@react-three/drei";
import * as THREE from "three";
import type { DefLink, Requirement } from "@/lib/definition";
import { DefinitionCar, QuietLight, type CarLook } from "@/three/DefinitionCar";
import { INTERIOR_ZONES, frameDir, poseFor, zoneToWorld, type CarFrame, type Vec3, type ZoneDef } from "@/three/frame";
import { PLACEHOLDER_FRAME } from "@/three/PlaceholderCar";
import { domainColor, isDashed, linkVerdict, rowFor, useDefinition } from "./data";
import { select, setView, useView } from "./store";
import { StageLayer, glide, type StageAnim } from "./StageLayer";

/** The car is normalised to 4.8 units; page 3 shows it at this scale so it sits inside the scan's camera range. */
export const CAR_SCALE = 0.72;
const XRAY_ZONES = new Set([...INTERIOR_ZONES, "underfloor"]);
const RISE_DELAY = 0.35, RISE = 1.1;   // seconds: the car starts rising while the volume is still sinking
const easeOut = (t: number) => 1 - Math.pow(1 - t, 3);
const INK = "#f2f4f7";

type Orbit = { target: THREE.Vector3; update: () => void };

export function DefinitionLayer({ active, sweepId, spread = 1 }: { active: boolean; sweepId: number; spread?: number }) {
  const def = useDefinition();
  const line = useView((s) => s.line);
  const selected = useView((s) => s.selected);
  const hover = useView((s) => s.hover);
  const domains = useView((s) => s.domains);
  const linkMode = useView((s) => s.links);
  const bundle = useView((s) => s.bundle);
  const pendingLinks = useView((s) => s.pendingLinks);   // optimistic link reviews
  const stage = useView((s) => s.stage);
  const { data } = def;
  // the car only comes up at the last stage; before it the requirements live on the plane (StageLayer)
  const carOn = active && stage === "car";
  const anim = useRef<StageAnim>({ rise: 0, split: 0, link: 0, fly: 0, flyWait: 0 });
  const [landed, setLanded] = useState(false);   // the requirements have flown onto the car: the pins take over

  const [frame, setFrame] = useState<CarFrame>(PLACEHOLDER_FRAME);
  const onFrame = useCallback((f: CarFrame) => setFrame((p) => (p.L === f.L && p.W === f.W && p.H === f.H ? p : f)), []);
  const model = data.models[line];

  /* what is on the car for this line */
  const reqs = useMemo(() => data.requirements.filter((r) => r.lines.includes(line)), [data, line]);
  const byKey = useMemo(() => new Map(data.requirements.map((r) => [r.key, r])), [data]);
  const passes = useCallback((r: Requirement) => !domains.length || domains.includes(r.domain), [domains]);
  const sel = selected ? byKey.get(selected) ?? null : null;
  const zoneOf = useCallback((r: Requirement) => r.zones.find((z) => data.zones[z]) ?? null, [data.zones]);
  const focusZone = sel ? zoneOf(sel) : null;

  /* the rise: the car (and its pins) come up as the volume sinks; leaving runs it back down */
  const group = useRef<THREE.Group>(null);
  const look = useRef<CarLook>({ show: 0, xray: 0 });
  const rise = useRef({ t: 0, wait: 0 });
  const [present, setPresent] = useState(active);
  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
  useEffect(() => { if (active) setPresent(true); }, [active]);
  useEffect(() => { if (carOn) rise.current.wait = reduced ? 0 : RISE_DELAY; }, [carOn, reduced]);
  useFrame((_, dt) => {
    const r = rise.current;
    const goal = carOn ? 1 : 0;
    if (carOn && r.wait > 0) r.wait -= dt;
    else if (r.t !== goal) {
      const step = reduced ? 1 : dt / RISE;
      r.t = goal > r.t ? Math.min(1, r.t + step) : Math.max(0, r.t - step * 1.6);
    }
    const e = easeOut(r.t);
    look.current.show = e;
    const xGoal = carOn && focusZone && XRAY_ZONES.has(focusZone) ? 1 : 0;
    look.current.xray += (xGoal - look.current.xray) * (reduced ? 1 : 1 - Math.exp(-dt * 5));
    if (Math.abs(look.current.xray - xGoal) < 0.003) look.current.xray = xGoal;
    if (group.current) group.current.position.y = -0.55 * (1 - e);
    if (!active && r.t === 0 && anim.current.rise === 0 && present) setPresent(false);
  });

  useCameraFlight(carOn, focusZone ? data.zones[focusZone] : null, frame, reduced);

  /* pins grouped by zone, in domain order then title, so a zone's fan reads the same way every time */
  const zones = useMemo(() => {
    const order = data.domains.map((d) => d.key);
    const m = new Map<string, Requirement[]>();
    for (const r of reqs) {
      const z = zoneOf(r);
      if (z) m.set(z, [...(m.get(z) ?? []), r]);
    }
    for (const list of m.values()) list.sort((a, b) => order.indexOf(a.domain) - order.indexOf(b.domain) || a.title.localeCompare(b.title));
    return [...m.entries()];
  }, [reqs, zoneOf, data.domains]);

  /* links between requirements both on this line */
  const onLine = useMemo(() => new Set(reqs.map((r) => r.key)), [reqs]);
  const bundleKeys = useMemo(() => new Set(data.bundles.find((b) => b.id === bundle)?.keys ?? []), [data.bundles, bundle]);
  const arcs = useMemo(() => {
    const out: { l: DefLink; a: Vec3; b: Vec3; level: "hot" | "warm" | "faint"; label: boolean }[] = [];
    for (const l of data.links) {
      if (!onLine.has(l.a) || !onLine.has(l.b)) continue;
      const ra = byKey.get(l.a)!, rb = byKey.get(l.b)!;
      const za = zoneOf(ra), zb = zoneOf(rb);
      if (!za || !zb) continue;
      const verdict = linkVerdict(l);
      const mine = !!selected && (l.a === selected || l.b === selected);
      if (verdict === "removed" && !mine) continue;
      const inBundle = bundleKeys.size > 0 && bundleKeys.has(l.a) && bundleKeys.has(l.b) && l.strength >= 2;
      const hovered = !!hover && (l.a === hover || l.b === hover);
      let level: "hot" | "warm" | "faint" | null;
      if (mine || inBundle) level = "hot";
      else if (hovered) level = "warm";
      else if (selected || bundleKeys.size) level = null;            // focus: only the selected requirement's links
      else if (linkMode === "off") level = null;
      else if (linkMode === "strong" && l.strength < 2) level = null;
      else level = passes(ra) && passes(rb) ? "faint" : null;
      if (!level) continue;
      const pa = zoneToWorld(data.zones[za].pos, frame), pb = zoneToWorld(data.zones[zb].pos, frame);
      if (za === zb) {   // same zone: open the two ends a little across the car so the loop is visible
        pa[2] -= 0.3; pb[2] += 0.3;
      }
      out.push({ l, a: pa, b: pb, level, label: level === "hot" });
    }
    return out;
  }, [data, onLine, byKey, zoneOf, selected, hover, bundleKeys, linkMode, passes, frame, pendingLinks]);

  const linkedToSel = useMemo(() => {
    if (!selected) return null;
    const s = new Set<string>([selected]);
    for (const l of data.links) if (linkVerdict(l) !== "removed") { if (l.a === selected) s.add(l.b); if (l.b === selected) s.add(l.a); }
    return s;
  }, [selected, data.links, pendingLinks]);

  const pinsOn = carOn && landed;
  if (!present) return null;
  return (
    <>
    <StageLayer active={active} data={data} reqs={reqs} line={line} frame={frame} carScale={CAR_SCALE} spread={spread}
                anim={anim} onLanded={setLanded} reduced={reduced} />
    <group ref={group}>
      <QuietLight />
      <group scale={CAR_SCALE}>
        <DefinitionCar url={model?.url ?? null} orientation={model?.orientation} look={look} onFrame={onFrame} />
        {carOn && <GroundRing frame={frame} />}
        {pinsOn && arcs.map((x) => <Arc key={`${x.l.id}`} {...x} frame={frame} sweepId={sweepId} reduced={reduced} />)}
        {pinsOn && zones.map(([z, list]) => (
          <ZonePins key={z} zone={z} def={data.zones[z]} frame={frame} list={list} line={line} selected={selected}
                    focus={focusZone === z} xray={!!focusZone && XRAY_ZONES.has(focusZone)} passes={passes} linked={linkedToSel}
                    bundle={bundleKeys} sweepId={sweepId} />
        ))}
      </group>
    </group>
    </>
  );
}

/* --------------------------------------------------------------------------------------------- camera */
// Flights move the camera and the orbit centre together, like the scan's reset glide; under reduced motion they jump.
function useCameraFlight(active: boolean, zone: ZoneDef | null, frame: CarFrame, reduced: boolean) {
  const controls = useThree((s) => s.controls) as unknown as Orbit | null;
  const camera = useThree((s) => s.camera);
  const aspect = useThree((s) => s.size.width / Math.max(1, s.size.height));
  const flight = useRef<{ t0: number; fromP: THREE.Vector3; fromT: THREE.Vector3; toP: THREE.Vector3; toT: THREE.Vector3; dur: number } | null>(null);
  useEffect(() => {
    if (!active) { flight.current = null; return; }
    if (!controls) return;
    const raw = poseFor(zone, frame);
    const pull = aspect < 1.25 ? Math.min(2.1, Math.pow(1.25 / aspect, 0.85)) : 1;
    const t = new THREE.Vector3(...raw.target).multiplyScalar(CAR_SCALE);
    const p = new THREE.Vector3(...raw.eye).multiplyScalar(CAR_SCALE).sub(t).multiplyScalar(pull).add(t);
    // a selected zone sits left of centre, clear of the inspector on the right (wide viewports only)
    if (zone && aspect > 1.25) {
      const right = new THREE.Vector3().subVectors(t, p).cross(new THREE.Vector3(0, 1, 0)).normalize();
      const shift = right.multiplyScalar(p.distanceTo(t) * 0.22);
      p.add(shift); t.add(shift);
    }
    flight.current = { t0: -1, fromP: camera.position.clone(), fromT: controls.target.clone(), toP: p, toT: t, dur: reduced ? 0 : zone ? 1.1 : 1.4 };
  }, [active, zone, frame, aspect, controls, camera, reduced]);
  useFrame(({ clock }) => {
    const f = flight.current;
    if (!f || !controls) return;
    if (f.t0 < 0) f.t0 = clock.elapsedTime;
    const p = f.dur ? Math.min(1, (clock.elapsedTime - f.t0) / f.dur) : 1;
    const e = easeOut(p);
    glide(f.fromP, f.fromT, f.toP, f.toT, e, camera.position, controls.target);
    controls.update();
    if (p >= 1) flight.current = null;
  });
}

/* --------------------------------------------------------------------------------------------- ground */
/** One hairline ellipse on the ground under the car, the scan's range-ring vocabulary (white at 10%). */
function GroundRing({ frame }: { frame: CarFrame }) {
  const geom = useMemo(() => {
    const pts: THREE.Vector3[] = [];
    for (let i = 0; i <= 160; i++) { const a = (i / 160) * Math.PI * 2; pts.push(new THREE.Vector3(Math.cos(a) * frame.L * 1.22, 0.002, Math.sin(a) * frame.W * 2.1)); }
    return new THREE.BufferGeometry().setFromPoints(pts);
  }, [frame]);
  return <lineLoop geometry={geom}><lineBasicMaterial color="#ffffff" transparent opacity={0.1} depthWrite={false} /></lineLoop>;
}

/* --------------------------------------------------------------------------------------------- arcs */
const WIDTH = { 1: 1, 2: 1.7, 3: 2.6 } as Record<number, number>;
const OPACITY = { hot: 0.92, warm: 0.6, faint: 0.2 };

const Arc = memo(function Arc({ l, a, b, level, label, frame, sweepId, reduced }: {
  l: DefLink; a: Vec3; b: Vec3; level: "hot" | "warm" | "faint"; label: boolean; frame: CarFrame; sweepId: number; reduced: boolean;
}) {
  const { pts, apex, tip, dir } = useMemo(() => {
    const A = new THREE.Vector3(...a), B = new THREE.Vector3(...b);
    const d = A.distanceTo(B);
    const mid = A.clone().lerp(B, 0.5);
    // over the roof for long links, a low hop between neighbours
    mid.y = Math.max(A.y, B.y) + frame.H * 0.35 + d * 0.22;
    const curve = new THREE.QuadraticBezierCurve3(A, mid, B);
    const pts = curve.getPoints(48);
    const forward = l.direction !== "b_to_a";
    const t = forward ? 0.8 : 0.2;
    const tan = curve.getTangent(t);
    return { pts, apex: curve.getPoint(0.5), tip: curve.getPoint(t), dir: forward ? tan : tan.negate() };
  }, [a, b, frame, l.direction]);
  const dashed = isDashed(l.relation);
  const ref = useRef<{ material: THREE.Material & { opacity: number } } | null>(null);
  const cone = useRef<THREE.Mesh>(null);
  const quat = useMemo(() => new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize()), [dir]);
  // a link that is new at this checkpoint brightens once when the sweep lands, then settles
  const pulse = useRef(-1);
  useEffect(() => { pulse.current = !reduced && l.state === "new" ? 0 : -1; }, [sweepId, l.state, reduced]);
  const base = OPACITY[level] * (l.strength >= 3 ? 1 : l.strength === 2 ? 0.9 : 0.75);
  useFrame((_, dt) => {
    const m = ref.current?.material;
    if (!m) return;
    let o = base;
    if (pulse.current >= 0) {
      pulse.current += dt;
      const p = pulse.current / 1.6;
      o = base + (1 - base) * Math.sin(Math.min(1, p) * Math.PI);
      if (p >= 1) pulse.current = -1;
    }
    m.opacity = o;
    const cm = cone.current?.material as THREE.MeshBasicMaterial | undefined;
    if (cm) cm.opacity = o;
  });
  return (
    <group>
      <Line ref={ref as never} points={pts} color={INK} lineWidth={(WIDTH[l.strength] ?? 1.4) * (level === "hot" ? 1.15 : 1)} transparent
            opacity={base} dashed={dashed} dashSize={0.07} gapSize={0.06} depthTest={false} depthWrite={false} renderOrder={level === "hot" ? 6 : 4} />
      {l.relation === "enables" && (
        <mesh ref={cone} position={tip} quaternion={quat} renderOrder={6}>
          <coneGeometry args={[0.045, 0.13, 12]} />
          <meshBasicMaterial color={INK} transparent opacity={base} depthTest={false} depthWrite={false} />
        </mesh>
      )}
      {label && (
        <Html position={apex} center zIndexRange={[13, 11]}>
          <div className="dlink-label" data-dashed={dashed ? "" : undefined}>{l.via}</div>
        </Html>
      )}
    </group>
  );
});

/* --------------------------------------------------------------------------------------------- pins */
// DOM pins (crisp marks, real buttons) anchored at the zone. A zone with several requirements fans them out in rows
// of four. Pins on the far side of the car dim, unless the body is in x-ray.
const ZonePins = memo(function ZonePins({ zone, def, frame, list, line, selected, focus, xray, passes, linked, bundle, sweepId }: {
  zone: string; def: ZoneDef; frame: CarFrame; list: Requirement[]; line: string; selected: string | null; focus: boolean; xray: boolean;
  passes: (r: Requirement) => boolean; linked: Set<string> | null; bundle: Set<string>; sweepId: number;
}) {
  const pos = useMemo(() => zoneToWorld(def.pos, frame), [def, frame]);
  const facing = useMemo(() => new THREE.Vector3(...frameDir(def.view)), [def]);
  const el = useRef<HTMLDivElement>(null);
  const world = useMemo(() => new THREE.Vector3(...pos).multiplyScalar(CAR_SCALE), [pos]);
  const v = useMemo(() => new THREE.Vector3(), []);
  const lastBehind = useRef<boolean | null>(null);
  useFrame(({ camera }) => {
    if (!el.current) return;
    const behind = !xray && !focus && v.copy(camera.position).sub(world).normalize().dot(facing) < -0.15;
    if (behind !== lastBehind.current) { lastBehind.current = behind; el.current.toggleAttribute("data-behind", behind); }
  });
  return (
    <Html position={pos} center zIndexRange={[14, 12]}>
      <div ref={el} className="dzone" data-zone={zone} data-focus={focus ? "" : undefined}>
        <div className="dzone-pins">
          {list.map((r) => {
            const on = r.key === selected;
            const dim = !passes(r) ? "off" : linked && !linked.has(r.key) ? "dim" : bundle.size && !bundle.has(r.key) ? "dim" : undefined;
            const changed = r.state === "changed" || r.state === "strengthened";
            const pulse = r.state === "new" || changed;
            const rec = rowFor(r, line);
            return (
              <button key={`${r.key}:${pulse ? sweepId : 0}`} type="button" className="dpin" data-state={r.state ?? "held"}
                      data-on={on ? "" : undefined} data-linked={linked?.has(r.key) && !on ? "" : undefined} data-dim={dim}
                      data-pulse={pulse ? "" : undefined} style={{ ["--c" as string]: domainColor(r.domain) }}
                      aria-label={`${r.title}${rec ? ` · ${rec.market}` : ""}`} aria-pressed={on}
                      onPointerEnter={(e) => setView({ hover: r.key, hoverPos: { x: e.clientX, y: e.clientY } })}
                      onPointerMove={(e) => setView({ hoverPos: { x: e.clientX, y: e.clientY } })}
                      onPointerLeave={() => setView({ hover: null, hoverPos: null })}
                      onClick={(e) => { e.stopPropagation(); select(on ? null : r.key); }}>
                <i aria-hidden />
              </button>
            );
          })}
        </div>
        <span className="dzone-label">{def.label}{list.length > 1 ? <b>{list.length}</b> : null}</span>
      </div>
    </Html>
  );
});
// Page-3 view state, shared by the HUD (DOM) and the definition layer inside the canvas without threading props
// through Scan/Scene. A tiny external store read with useSyncExternalStore.
import { useSyncExternalStore } from "react";
import type { ChoosableRung, LineName } from "@/lib/definition";
import type { DefStage } from "./stages";

export type LinkMode = "strong" | "all" | "off";

export interface DefView {
  selected: string | null;        // requirement key
  hover: string | null;           // requirement key under the pointer (pin or list row)
  hoverPos: { x: number; y: number } | null;
  line: LineName;
  domains: string[];              // empty = all
  links: LinkMode;
  bundle: string | null;          // highlighted bundle id
  /** optimistic PM choices, key `${req}|${line}|${market}` → rung (cleared when the server state arrives) */
  pending: Record<string, ChoosableRung>;
  /** optimistic link reviews, link id → verdict */
  pendingLinks: Record<string, "confirmed" | "removed">;
  /** the definition stage in view (stages.ts); set by the funnel, read by the 3D stage layer */
  stage: DefStage;
  /** true while the arrival play steps through the stages on its own */
  auto: boolean;
  /** area diamond / domain group under the pointer (lights up their requirements) */
  hoverArea: string | null;
  hoverDomain: string | null;
}

const LINE_KEY = "definition.line";
const readLine = (): LineName => {
  try { const v = localStorage.getItem(LINE_KEY); return v === "1 Series" || v === "7 Series" ? v : "5 Series"; } catch { return "5 Series"; }
};

let state: DefView = {
  selected: null, hover: null, hoverPos: null, line: readLine(), domains: [], links: "strong", bundle: null, pending: {}, pendingLinks: {},
  stage: "areas", auto: false, hoverArea: null, hoverDomain: null,
};
const subs = new Set<() => void>();

export function setView(patch: Partial<DefView> | ((s: DefView) => Partial<DefView>)) {
  const p = typeof patch === "function" ? patch(state) : patch;
  state = { ...state, ...p };
  if (p.line) { try { localStorage.setItem(LINE_KEY, p.line); } catch { /* private mode */ } }
  subs.forEach((f) => f());
}
export const getView = () => state;
const subscribe = (f: () => void) => { subs.add(f); return () => { subs.delete(f); }; };

export function useView<T>(pick: (s: DefView) => T): T {
  return useSyncExternalStore(subscribe, () => pick(state));
}

export const select = (key: string | null) => setView({ selected: key, hover: null, hoverPos: null });
// Stepping through the definition layer on page 3 (frontend only: every stage's output is already in /api/definition).
// areas: the requirement-area diamonds rise from their Structure ring to a plane above the volume, which sinks away.
// drafted: each diamond splits into its requirements, which settle into one group per vehicle domain.
// specified: each requirement shows its recommended target; a "?" marks open gaps.
// linked: the couplings between requirements appear as arcs between the groups.
// car: today's car rises and every requirement flies to its zone on it.
import type { DefData } from "./data";

export const DEF_STAGES = ["areas", "drafted", "specified", "linked", "car"] as const;
export type DefStage = (typeof DEF_STAGES)[number];
export const DEF_STAGE_LABEL: Record<DefStage, string> = {
  areas: "Areas", drafted: "Drafted", specified: "Specified", linked: "Linked", car: "On the car",
};

export const defAtLeast = (s: DefStage, t: DefStage) => DEF_STAGES.indexOf(s) >= DEF_STAGES.indexOf(t);

/** Stages whose output this checkpoint has, in order. Areas need Structure; the rest need drafted requirements. */
export function defDoneStages(def: DefData, structureReady: boolean): DefStage[] {
  const d = def.data;
  const has = d.requirements.length > 0;
  return DEF_STAGES.filter((s) => {
    if (s === "areas") return structureReady;
    if (!has) return false;
    if (s === "specified") return def.sample || !!d.runs.specify || d.requirements.some((r) => r.ladder.length > 0);
    if (s === "linked") return def.sample || !!d.runs.couple || d.links.length > 0;
    return true;
  });
}

toolUseResult.stdout:
// Page 3 inside the shared scan canvas. Before the last stage the requirements live on a plane above the volume
// (StageLayer: areas → drafted → specified → linked); on the "car" stage today's car rises at the centre, the
// requirement definitions sit on it as pins at their car zone (colour = domain, mark shape = track state), and the
// couplings between requirements run as arcs over and through the car between their zones (solid = synergy /
// enables, dashed = conflicts / competes for, width = strength, the shared resource named at the apex).
// Selecting a requirement flies the camera to its zone (x-ray for interior zones and the battery floor).
import { memo, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import { Html, Line } from "@react-three/drei";
import * as THREE from "three";
import type { DefLink, Requirement } from "@/lib/definition";
import { DefinitionCar, QuietLight, type CarLook } from "@/three/DefinitionCar";
import { INTERIOR_ZONES, frameDir, poseFor, zoneToWorld, type CarFrame, type Vec3, type ZoneDef } from "@/three/frame";
import { PLACEHOLDER_FRAME } from "@/three/PlaceholderCar";
import { domainColor, isDashed, linkVerdict, rowFor, useDefinition } from "./data";
import { select, setView, useView } from "./store";
import { StageLayer, glide, type StageAnim } from "./StageLayer";

/** The car is normalised to 4.8 units; page 3 shows it at this scale so it sits inside the scan's camera range. */
export const CAR_SCALE = 0.72;
const XRAY_ZONES = new Set([...INTERIOR_ZONES, "underfloor"]);
const RISE_DELAY = 0.35, RISE = 1.1;   // seconds: the car starts rising while the volume is still sinking
const easeOut = (t: number) => 1 - Math.pow(1 - t, 3);
const INK = "#f2f4f7";

type Orbit = { target: THREE.Vector3; update: () => void };

export function DefinitionLayer({ active, sweepId, spread = 1 }: { active: boolean; sweepId: number; spread?: number }) {
  const def = useDefinition();
  const line = useView((s) => s.line);
  const selected = useView((s) => s.selected);
  const hover = useView((s) => s.hover);
  const domains = useView((s) => s.domains);
  const linkMode = useView((s) => s.links);
  const bundle = useView((s) => s.bundle);
  const pendingLinks = useView((s) => s.pendingLinks);   // optimistic link reviews
  const stage = useView((s) => s.stage);
  const { data } = def;
  // the car only comes up at the last stage; before it the requirements live on the plane (StageLayer)
  const carOn = active && stage === "car";
  const anim = useRef<StageAnim>({ rise: 0, split: 0, link: 0, fly: 0, flyWait: 0 });
  const [landed, setLanded] = useState(false);   // the requirements have flown onto the car: the pins take over

  const [frame, setFrame] = useState<CarFrame>(PLACEHOLDER_FRAME);
  const onFrame = useCallback((f: CarFrame) => setFrame((p) => (p.L === f.L && p.W === f.W && p.H === f.H ? p : f)), []);
  const model = data.models[line];

  /* what is on the car for this line */
  const reqs = useMemo(() => data.requirements.filter((r) => r.lines.includes(line)), [data, line]);
  const byKey = useMemo(() => new Map(data.requirements.map((r) => [r.key, r])), [data]);
  const passes = useCallback((r: Requirement) => !domains.length || domains.includes(r.domain), [domains]);
  const sel = selected ? byKey.get(selected) ?? null : null;
  const zoneOf = useCallback((r: Requirement) => r.zones.find((z) => data.zones[z]) ?? null, [data.zones]);
  const focusZone = sel ? zoneOf(sel) : null;

  /* the rise: the car (and its pins) come up as the volume sinks; leaving runs it back down */
  const group = useRef<THREE.Group>(null);
  const look = useRef<CarLook>({ show: 0, xray: 0 });
  const rise = useRef({ t: 0, wait: 0 });
  const [present, setPresent] = useState(active);
  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
  useEffect(() => { if (active) setPresent(true); }, [active]);
  useEffect(() => { if (carOn) rise.current.wait = reduced ? 0 : RISE_DELAY; }, [carOn, reduced]);
  useFrame((_, dt) => {
    const r = rise.current;
    const goal = carOn ? 1 : 0;
    if (carOn && r.wait > 0) r.wait -= dt;
    else if (r.t !== goal) {
      const step = reduced ? 1 : dt / RISE;
      r.t = goal > r.t ? Math.min(1, r.t + step) : Math.max(0, r.t - step * 1.6);
    }
    const e = easeOut(r.t);
    look.current.show = e;
    const xGoal = carOn && focusZone && XRAY_ZONES.has(focusZone) ? 1 : 0;
    look.current.xray += (xGoal - look.current.xray) * (reduced ? 1 : 1 - Math.exp(-dt * 5));
    if (Math.abs(look.current.xray - xGoal) < 0.003) look.current.xray = xGoal;
    if (group.current) group.current.position.y = -0.55 * (1 - e);
    if (!active && r.t === 0 && anim.current.rise === 0 && present) setPresent(false);
  });

  useCameraFlight(carOn, focusZone ? data.zones[focusZone] : null, frame, reduced);

  /* pins grouped by zone, in domain order then title, so a zone's fan reads the same way every time */
  const zones = useMemo(() => {
    const order = data.domains.map((d) => d.key);
    const m = new Map<string, Requirement[]>();
    for (const r of reqs) {
      const z = zoneOf(r);
      if (z) m.set(z, [...(m.get(z) ?? []), r]);
    }
    for (const list of m.values()) list.sort((a, b) => order.indexOf(a.domain) - order.indexOf(b.domain) || a.title.localeCompare(b.title));
    return [...m.entries()];
  }, [reqs, zoneOf, data.domains]);

  /* links between requirements both on this line */
  const onLine = useMemo(() => new Set(reqs.map((r) => r.key)), [reqs]);
  const bundleKeys = useMemo(() => new Set(data.bundles.find((b) => b.id === bundle)?.keys ?? []), [data.bundles, bundle]);
  const arcs = useMemo(() => {
    const out: { l: DefLink; a: Vec3; b: Vec3; level: "hot" | "warm" | "faint"; label: boolean }[] = [];
    for (const l of data.links) {
      if (!onLine.has(l.a) || !onLine.has(l.b)) continue;
      const ra = byKey.get(l.a)!, rb = byKey.get(l.b)!;
      const za = zoneOf(ra), zb = zoneOf(rb);
      if (!za || !zb) continue;
      const verdict = linkVerdict(l);
      const mine = !!selected && (l.a === selected || l.b === selected);
      if (verdict === "removed" && !mine) continue;
      const inBundle = bundleKeys.size > 0 && bundleKeys.has(l.a) && bundleKeys.has(l.b) && l.strength >= 2;
      const hovered = !!hover && (l.a === hover || l.b === hover);
      let level: "hot" | "warm" | "faint" | null;
      if (mine || inBundle) level = "hot";
      else if (hovered) level = "warm";
      else if (selected || bundleKeys.size) level = null;            // focus: only the selected requirement's links
      else if (linkMode === "off") level = null;
      else if (linkMode === "strong" && l.strength < 2) level = null;
      else level = passes(ra) && passes(rb) ? "faint" : null;
      if (!level) continue;
      const pa = zoneToWorld(data.zones[za].pos, frame), pb = zoneToWorld(data.zones[zb].pos, frame);
      if (za === zb) {   // same zone: open the two ends a little across the car so the loop is visible
        pa[2] -= 0.3; pb[2] += 0.3;
      }
      out.push({ l, a: pa, b: pb, level, label: level === "hot" });
    }
    return out;
  }, [data, onLine, byKey, zoneOf, selected, hover, bundleKeys, linkMode, passes, frame, pendingLinks]);

  const linkedToSel = useMemo(() => {
    if (!selected) return null;
    const s = new Set<string>([selected]);
    for (const l of data.links) if (linkVerdict(l) !== "removed") { if (l.a === selected) s.add(l.b); if (l.b === selected) s.add(l.a); }
    return s;
  }, [selected, data.links, pendingLinks]);

  const pinsOn = carOn && landed;
  if (!present) return null;
  return (
    <>
    <StageLayer active={active} data={data} reqs={reqs} line={line} frame={frame} carScale={CAR_SCALE} spread={spread}
                anim={anim} onLanded={setLanded} reduced={reduced} />
    <group ref={group}>
      <QuietLight />
      <group scale={CAR_SCALE}>
        <DefinitionCar url={model?.url ?? null} orientation={model?.orientation} look={look} onFrame={onFrame} />
        {carOn && <GroundRing frame={frame} />}
        {pinsOn && arcs.map((x) => <Arc key={`${x.l.id}`} {...x} frame={frame} sweepId={sweepId} reduced={reduced} />)}
        {pinsOn && zones.map(([z, list]) => (
          <ZonePins key={z} zone={z} def={data.zones[z]} frame={frame} list={list} line={line} selected={selected}
                    focus={focusZone === z} xray={!!focusZone && XRAY_ZONES.has(focusZone)} passes={passes} linked={linkedToSel}
                    bundle={bundleKeys} sweepId={sweepId} />
        ))}
      </group>
    </group>
    </>
  );
}

/* --------------------------------------------------------------------------------------------- camera */
// Flights move the camera and the orbit centre together, like the scan's reset glide; under reduced motion they jump.
function useCameraFlight(active: boolean, zone: ZoneDef | null, frame: CarFrame, reduced: boolean) {
  const controls = useThree((s) => s.controls) as unknown as Orbit | null;
  const camera = useThree((s) => s.camera);
  const aspect = useThree((s) => s.size.width / Math.max(1, s.size.height));
  const flight = useRef<{ t0: number; fromP: THREE.Vector3; fromT: THREE.Vector3; toP: THREE.Vector3; toT: THREE.Vector3; dur: number } | null>(null);
  useEffect(() => {
    if (!active) { flight.current = null; return; }
    if (!controls) return;
    const raw = poseFor(zone, frame);
    const pull = aspect < 1.25 ? Math.min(2.1, Math.pow(1.25 / aspect, 0.85)) : 1;
    const t = new THREE.Vector3(...raw.target).multiplyScalar(CAR_SCALE);
    const p = new THREE.Vector3(...raw.eye).multiplyScalar(CAR_SCALE).sub(t).multiplyScalar(pull).add(t);
    // a selected zone sits left of centre, clear of the inspector on the right (wide viewports only)
    if (zone && aspect > 1.25) {
      const right = new THREE.Vector3().subVectors(t, p).cross(new THREE.Vector3(0, 1, 0)).normalize();
      const shift = right.multiplyScalar(p.distanceTo(t) * 0.22);
      p.add(shift); t.add(shift);
    }
    flight.current = { t0: -1, fromP: camera.position.clone(), fromT: controls.target.clone(), toP: p, toT: t, dur: reduced ? 0 : zone ? 1.1 : 1.4 };
  }, [active, zone, frame, aspect, controls, camera, reduced]);
  useFrame(({ clock }) => {
    const f = flight.current;
    if (!f || !controls) return;
    if (f.t0 < 0) f.t0 = clock.elapsedTime;
    const p = f.dur ? Math.min(1, (clock.elapsedTime - f.t0) / f.dur) : 1;
    const e = easeOut(p);
    glide(f.fromP, f.fromT, f.toP, f.toT, e, camera.position, controls.target);
    controls.update();
    if (p >= 1) flight.current = null;
  });
}

/* --------------------------------------------------------------------------------------------- ground */
/** One hairline ellipse on the ground under the car, the scan's range-ring vocabulary (white at 10%). */
function GroundRing({ frame }: { frame: CarFrame }) {
  const geom = useMemo(() => {
    const pts: THREE.Vector3[] = [];
    for (let i = 0; i <= 160; i++) { const a = (i / 160) * Math.PI * 2; pts.push(new THREE.Vector3(Math.cos(a) * frame.L * 1.22, 0.002, Math.sin(a) * frame.W * 2.1)); }
    return new THREE.BufferGeometry().setFromPoints(pts);
  }, [frame]);
  return <lineLoop geometry={geom}><lineBasicMaterial color="#ffffff" transparent opacity={0.1} depthWrite={false} /></lineLoop>;
}

/* --------------------------------------------------------------------------------------------- arcs */
const WIDTH = { 1: 1, 2: 1.7, 3: 2.6 } as Record<number, number>;
const OPACITY = { hot: 0.92, warm: 0.6, faint: 0.2 };

const Arc = memo(function Arc({ l, a, b, level, label, frame, sweepId, reduced }: {
  l: DefLink; a: Vec3; b: Vec3; level: "hot" | "warm" | "faint"; label: boolean; frame: CarFrame; sweepId: number; reduced: boolean;
}) {
  const { pts, apex, tip, dir } = useMemo(() => {
    const A = new THREE.Vector3(...a), B = new THREE.Vector3(...b);
    const d = A.distanceTo(B);
    const mid = A.clone().lerp(B, 0.5);
    // over the roof for long links, a low hop between neighbours
    mid.y = Math.max(A.y, B.y) + frame.H * 0.35 + d * 0.22;
    const curve = new THREE.QuadraticBezierCurve3(A, mid, B);
    const pts = curve.getPoints(48);
    const forward = l.direction !== "b_to_a";
    const t = forward ? 0.8 : 0.2;
    const tan = curve.getTangent(t);
    return { pts, apex: curve.getPoint(0.5), tip: curve.getPoint(t), dir: forward ? tan : tan.negate() };
  }, [a, b, frame, l.direction]);
  const dashed = isDashed(l.relation);
  const ref = useRef<{ material: THREE.Material & { opacity: number } } | null>(null);
  const cone = useRef<THREE.Mesh>(null);
  const quat = useMemo(() => new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize()), [dir]);
  // a link that is new at this checkpoint brightens once when the sweep lands, then settles
  const pulse = useRef(-1);
  useEffect(() => { pulse.current = !reduced && l.state === "new" ? 0 : -1; }, [sweepId, l.state, reduced]);
  const base = OPACITY[level] * (l.strength >= 3 ? 1 : l.strength === 2 ? 0.9 : 0.75);
  useFrame((_, dt) => {
    const m = ref.current?.material;
    if (!m) return;
    let o = base;
    if (pulse.current >= 0) {
      pulse.current += dt;
      const p = pulse.current / 1.6;
      o = base + (1 - base) * Math.sin(Math.min(1, p) * Math.PI);
      if (p >= 1) pulse.current = -1;
    }
    m.opacity = o;
    const cm = cone.current?.material as THREE.MeshBasicMaterial | undefined;
    if (cm) cm.opacity = o;
  });
  return (
    <group>
      <Line ref={ref as never} points={pts} color={INK} lineWidth={(WIDTH[l.strength] ?? 1.4) * (level === "hot" ? 1.15 : 1)} transparent
            opacity={base} dashed={dashed} dashSize={0.07} gapSize={0.06} depthTest={false} depthWrite={false} renderOrder={level === "hot" ? 6 : 4} />
      {l.relation === "enables" && (
        <mesh ref={cone} position={tip} quaternion={quat} renderOrder={6}>
          <coneGeometry args={[0.045, 0.13, 12]} />
          <meshBasicMaterial color={INK} transparent opacity={base} depthTest={false} depthWrite={false} />
        </mesh>
      )}
      {label && (
        <Html position={apex} center zIndexRange={[13, 11]}>
          <div className="dlink-label" data-dashed={dashed ? "" : undefined}>{l.via}</div>
        </Html>
      )}
    </group>
  );
});

/* --------------------------------------------------------------------------------------------- pins */
// DOM pins (crisp marks, real buttons) anchored at the zone. A zone with several requirements fans them out in rows
// of four. Pins on the far side of the car dim, unless the body is in x-ray.
const ZonePins = memo(function ZonePins({ zone, def, frame, list, line, selected, focus, xray, passes, linked, bundle, sweepId }: {
  zone: string; def: ZoneDef; frame: CarFrame; list: Requirement[]; line: string; selected: string | null; focus: boolean; xray: boolean;
  passes: (r: Requirement) => boolean; linked: Set<string> | null; bundle: Set<string>; sweepId: number;
}) {
  const pos = useMemo(() => zoneToWorld(def.pos, frame), [def, frame]);
  const facing = useMemo(() => new THREE.Vector3(...frameDir(def.view)), [def]);
  const el = useRef<HTMLDivElement>(null);
  const world = useMemo(() => new THREE.Vector3(...pos).multiplyScalar(CAR_SCALE), [pos]);
  const v = useMemo(() => new THREE.Vector3(), []);
  const lastBehind = useRef<boolean | null>(null);
  useFrame(({ camera }) => {
    if (!el.current) return;
    const behind = !xray && !focus && v.copy(camera.position).sub(world).normalize().dot(facing) < -0.15;
    if (behind !== lastBehind.current) { lastBehind.current = behind; el.current.toggleAttribute("data-behind", behind); }
  });
  return (
    <Html position={pos} center zIndexRange={[14, 12]}>
      <div ref={el} className="dzone" data-zone={zone} data-focus={focus ? "" : undefined}>
        <div className="dzone-pins">
          {list.map((r) => {
            const on = r.key === selected;
            const dim = !passes(r) ? "off" : linked && !linked.has(r.key) ? "dim" : bundle.size && !bundle.has(r.key) ? "dim" : undefined;
            const changed = r.state === "changed" || r.state === "strengthened";
            const pulse = r.state === "new" || changed;
            const rec = rowFor(r, line);
            return (
              <button key={`${r.key}:${pulse ? sweepId : 0}`} type="button" className="dpin" data-state={r.state ?? "held"}
                      data-on={on ? "" : undefined} data-linked={linked?.has(r.key) && !on ? "" : undefined} data-dim={dim}
                      data-pulse={pulse ? "" : undefined} style={{ ["--c" as string]: domainColor(r.domain) }}
                      aria-label={`${r.title}${rec ? ` · ${rec.market}` : ""}`} aria-pressed={on}
                      onPointerEnter={(e) => setView({ hover: r.key, hoverPos: { x: e.clientX, y: e.clientY } })}
                      onPointerMove={(e) => setView({ hoverPos: { x: e.clientX, y: e.clientY } })}
                      onPointerLeave={() => setView({ hover: null, hoverPos: null })}
                      onClick={(e) => { e.stopPropagation(); select(on ? null : r.key); }}>
                <i aria-hidden />
              </button>
            );
          })}
        </div>
        <span className="dzone-label">{def.label}{list.length > 1 ? <b>{list.length}</b> : null}</span>
      </div>
    </Html>
  );
});
// Page-3 view state, shared by the HUD (DOM) and the definition layer inside the canvas without threading props
// through Scan/Scene. A tiny external store read with useSyncExternalStore.
import { useSyncExternalStore } from "react";
import type { ChoosableRung, LineName } from "@/lib/definition";
import type { DefStage } from "./stages";

export type LinkMode = "strong" | "all" | "off";

export interface DefView {
  selected: string | null;        // requirement key
  hover: string | null;           // requirement key under the pointer (pin or list row)
  hoverPos: { x: number; y: number } | null;
  line: LineName;
  domains: string[];              // empty = all
  links: LinkMode;
  bundle: string | null;          // highlighted bundle id
  /** optimistic PM choices, key `${req}|${line}|${market}` → rung (cleared when the server state arrives) */
  pending: Record<string, ChoosableRung>;
  /** optimistic link reviews, link id → verdict */
  pendingLinks: Record<string, "confirmed" | "removed">;
  /** the definition stage in view (stages.ts); set by the funnel, read by the 3D stage layer */
  stage: DefStage;
  /** true while the arrival play steps through the stages on its own */
  auto: boolean;
  /** area diamond / domain group under the pointer (lights up their requirements) */
  hoverArea: string | null;
  hoverDomain: string | null;
}

const LINE_KEY = "definition.line";
const readLine = (): LineName => {
  try { const v = localStorage.getItem(LINE_KEY); return v === "1 Series" || v === "7 Series" ? v : "5 Series"; } catch { return "5 Series"; }
};

let state: DefView = {
  selected: null, hover: null, hoverPos: null, line: readLine(), domains: [], links: "strong", bundle: null, pending: {}, pendingLinks: {},
  stage: "areas", auto: false, hoverArea: null, hoverDomain: null,
};
const subs = new Set<() => void>();

export function setView(patch: Partial<DefView> | ((s: DefView) => Partial<DefView>)) {
  const p = typeof patch === "function" ? patch(state) : patch;
  state = { ...state, ...p };
  if (p.line) { try { localStorage.setItem(LINE_KEY, p.line); } catch { /* private mode */ } }
  subs.forEach((f) => f());
}
export const getView = () => state;
const subscribe = (f: () => void) => { subs.add(f); return () => { subs.delete(f); }; };

export function useView<T>(pick: (s: DefView) => T): T {
  return useSyncExternalStore(subscribe, () => pick(state));
}

export const select = (key: string | null) => setView({ selected: key, hover: null, hoverPos: null });
// Stepping through the definition layer on page 3 (frontend only: every stage's output is already in /api/definition).
// areas: the requirement-area diamonds rise from their Structure ring to a plane above the volume, which sinks away.
// drafted: each diamond splits into its requirements, which settle into one group per vehicle domain.
// specified: each requirement shows its recommended target; a "?" marks open gaps.
// linked: the couplings between requirements appear as arcs between the groups.
// car: today's car rises and every requirement flies to its zone on it.
import type { DefData } from "./data";

export const DEF_STAGES = ["areas", "drafted", "specified", "linked", "car"] as const;
export type DefStage = (typeof DEF_STAGES)[number];
export const DEF_STAGE_LABEL: Record<DefStage, string> = {
  areas: "Areas", drafted: "Drafted", specified: "Specified", linked: "Linked", car: "On the car",
};

export const defAtLeast = (s: DefStage, t: DefStage) => DEF_STAGES.indexOf(s) >= DEF_STAGES.indexOf(t);

/** Stages whose output this checkpoint has, in order. Areas need Structure; the rest need drafted requirements. */
export function defDoneStages(def: DefData, structureReady: boolean): DefStage[] {
  const d = def.data;
  const has = d.requirements.length > 0;
  return DEF_STAGES.filter((s) => {
    if (s === "areas") return structureReady;
    if (!has) return false;
    if (s === "specified") return def.sample || !!d.runs.specify || d.requirements.some((r) => r.ladder.length > 0);
    if (s === "linked") return def.sample || !!d.runs.couple || d.links.length > 0;
    return true;
  });
}

