import { useMemo } from "react";
import { useMutation, useQuery } from "@tanstack/react-query";
import { api, getActor, queryClient } from "@/lib/api";
import { useCheckpoint } from "@/state/checkpoint";
import type {
  ChoiceBody, ChoosableRung, DefinitionPayload, DefLink, LadderRow, LineName, LinkReviewBody, Requirement, RequirementDetail,
} from "@/lib/definition";
import { bundlesOf, fixtureDetail, fixtureFor } from "./fixture";
import { getView, setView } from "./store";

export const LINES: LineName[] = ["1 Series", "5 Series", "7 Series"];

/** One categorical hue per vehicle domain, validated on black; never sweep blue, never loss amber. */
export const DOMAIN_COLOR: Record<string, string> = {
  exterior: "#d95926",   // vermilion
  interior: "#199e70",   // aqua green
  powertrain: "#c98500", // ochre
  chassis: "#d55181",    // magenta
  assist: "#9b72e8",     // violet
  digital: "#1fa8b8",    // teal
  variants: "#a08a78",   // taupe
  quality: "#8f9a5a",    // olive
};
export const domainColor = (d: string) => DOMAIN_COLOR[d] ?? "#b4bac4";

export const RELATION_NAME: Record<string, string> = {
  conflicts: "Conflicts", competes_for: "Competes for", enables: "Enables", synergy: "Synergy",
};
export const isDashed = (r: string) => r === "conflicts" || r === "competes_for";

export interface DefData {
  data: DefinitionPayload;
  sample: boolean;            // true: fixture (API missing or not ready at this checkpoint)
  why: string | null;         // why the sample is shown
  pending: boolean;
}

export function useDefinition(): DefData {
  const { cp } = useCheckpoint();
  const q = useQuery({
    queryKey: ["definition", cp],
    queryFn: () => api.get<DefinitionPayload>(`/api/definition?cp=${cp}`),
    retry: false, staleTime: 15_000, placeholderData: (prev) => prev,
    // keep asking while the pipeline is still filling it, so the page switches to live data on its own
    refetchInterval: (s) => (s.state.data?.ready && s.state.data.checkpoint === cp ? false : 10_000),
  });
  return useMemo(() => {
    const live = q.data?.ready && q.data.checkpoint === cp ? q.data : null;
    if (live) return { data: { ...live, bundles: live.bundles ?? bundlesOf(live.links) }, sample: false, why: null, pending: false };
    const fx = fixtureFor(cp);
    // the zones and models of the live payload are real even before the pipeline has run
    if (q.data?.zones && Object.keys(q.data.zones).length) fx.zones = q.data.zones;
    if (q.data?.models && Object.keys(q.data.models).length) fx.models = { ...fx.models, ...q.data.models };
    const why = q.isError ? "Definition API not available" : q.data && !q.data.ready ? "Pipeline has not run at this checkpoint" : "Waiting for the API";
    return { data: fx, sample: true, why, pending: q.isPending };
  }, [q.data, q.isError, q.isPending, cp]);
}

export function useRequirementDetail(key: string | null, def: DefData) {
  const { cp } = useCheckpoint();
  const live = !def.sample;
  const q = useQuery({
    queryKey: ["definition-req", key, cp],
    queryFn: () => api.get<RequirementDetail>(`/api/definition/requirement/${encodeURIComponent(key!)}?cp=${cp}`),
    enabled: !!key && live, retry: false, staleTime: 15_000,
  });
  return useMemo(() => {
    if (!key) return null;
    if (live && q.data) return q.data;
    const r = def.data.requirements.find((x) => x.key === key);
    return r ? (live ? { ...r, evidence: [], facts: [], area: null, history: [] } as RequirementDetail : fixtureDetail(r)) : null;
  }, [key, live, q.data, def.data]);
}

/* --------------------------------------------------------------------------------------------- derived */
export const rowKey = (req: string, r: Pick<LadderRow, "line" | "market">) => `${req}|${r.line}|${r.market}`;

/** The rung the PM chose (optimistic first), or null. */
export function chosenRung(req: string, r: LadderRow): ChoosableRung | null {
  return getView().pending[rowKey(req, r)] ?? r.choice?.level ?? null;
}

export function linkVerdict(l: DefLink): "confirmed" | "removed" | "added" | null {
  return getView().pendingLinks[String(l.id)] ?? l.review?.verdict ?? null;
}

/** First ladder row for the line (the one shown on the pin and in the list). */
export const rowFor = (r: Requirement, line: string) => r.ladder.find((x) => x.line === line) ?? null;

export function fmtLevel(v: number | null | undefined, unit: string | undefined) {
  if (v == null) return "?";
  const n = Math.abs(v) >= 100 ? Math.round(v).toLocaleString("en-US") : String(Math.round(v * 10) / 10);
  if (!unit) return n;
  return unit.startsWith("%") || unit === "/ 10" ? `${n}${unit === "/ 10" ? "" : "%"}` : `${n} ${unit}`;
}

/* --------------------------------------------------------------------------------------------- writes */
export function useChoice(def: DefData) {
  const { cp } = useCheckpoint();
  return useMutation({
    mutationFn: async (b: Omit<ChoiceBody, "actor">) => {
      setView((s) => ({ pending: { ...s.pending, [`${b.key}|${b.line}|${b.market}`]: b.level } }));
      if (def.sample) return { sample: true };
      return api.post("/api/definition/choice", { ...b, actor: getActor() });
    },
    onError: (_e, b) => setView((s) => { const p = { ...s.pending }; delete p[`${b.key}|${b.line}|${b.market}`]; return { pending: p }; }),
    onSuccess: async (_r, b) => {
      if (def.sample) return;
      await queryClient.invalidateQueries({ queryKey: ["definition", cp] });
      await queryClient.invalidateQueries({ queryKey: ["definition-req", b.key] });
      setView((s) => { const p = { ...s.pending }; delete p[`${b.key}|${b.line}|${b.market}`]; return { pending: p }; });
    },
  });
}

export function useLinkReview(def: DefData) {
  const { cp } = useCheckpoint();
  return useMutation({
    mutationFn: async ({ link, ...b }: Omit<LinkReviewBody, "actor"> & { link: DefLink }) => {
      if (b.verdict !== "added") setView((s) => ({ pendingLinks: { ...s.pendingLinks, [String(link.id)]: b.verdict as "confirmed" | "removed" } }));
      if (def.sample) return { sample: true };
      return api.post("/api/definition/link-review", { ...b, actor: getActor() });
    },
    onError: (_e, { link }) => setView((s) => { const p = { ...s.pendingLinks }; delete p[String(link.id)]; return { pendingLinks: p }; }),
    onSuccess: async (_r, { link }) => {
      if (def.sample) return;
      await queryClient.invalidateQueries({ queryKey: ["definition", cp] });
      setView((s) => { const p = { ...s.pendingLinks }; delete p[String(link.id)]; return { pendingLinks: p }; });
    },
  });
}
// Pure car-frame math (no React, no WebGL) so it can be unit-tested.
//
// Normalised car frame: f along the length (-1 rear … +1 front), r across (-1 left … +1 right, seen from the
// driver's seat), h up (0 ground … 1 roof). After normalisation every car sits in world space with
// front = +X, up = +Y, centred on the origin, wheels on y = 0. The right-hand side is front × up = +Z.

export type Vec3 = [number, number, number];
export type Axis = "+x" | "-x" | "+y" | "-y" | "+z" | "-z";
export type Orientation = { up: Axis; front: Axis };

export type ZoneDef = { label: string; pos: Vec3; view: Vec3; dist: number };

/** World-space frame of a normalised car. L = half-length, W = half-width, H = height (roof). */
export type CarFrame = { L: number; W: number; H: number };

export const DEFAULT_ORIENTATION: Orientation = { up: "+y", front: "+z" };

export const WORLD_FRONT: Vec3 = [1, 0, 0];
export const WORLD_UP: Vec3 = [0, 1, 0];
export const cross = (a: Vec3, b: Vec3): Vec3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
/** right = front × up → +Z in world. */
export const WORLD_RIGHT: Vec3 = cross(WORLD_FRONT, WORLD_UP);

export function axisVec(a: Axis): Vec3 {
  const s = a[0] === "-" ? -1 : 1;
  const i = a[1] === "x" ? 0 : a[1] === "y" ? 1 : 2;
  const v: Vec3 = [0, 0, 0];
  v[i] = s;
  return v;
}

/**
 * Row-major 3×3 rotation that maps the model's local front → world +X, local up → world +Y and
 * local right (front × up) → world right (+Z). Rows are front, up, right (an orthonormal basis, det = +1).
 * Returns null when front and up are parallel (invalid orientation).
 */
export function orientationMatrix(o: Orientation): number[] | null {
  const f = axisVec(o.front);
  const u = axisVec(o.up);
  const r = cross(f, u);
  if (r[0] === 0 && r[1] === 0 && r[2] === 0) return null;
  // world = M · local, with M rows expressed so that M·f = X, M·u = Y, M·r = Z (r maps to WORLD_RIGHT = +Z).
  return [...f, ...u, ...r];
}

/** Frame from the normalised bounding-box size (world units, after rotation + scale). */
export function frameFromSize(size: Vec3): CarFrame {
  return { L: size[0] / 2, W: size[2] / 2, H: size[1] };
}

/** A normalised zone position [f, r, h] → world [x, y, z]. */
export function zoneToWorld(pos: Vec3, frame: CarFrame): Vec3 {
  const [f, r, h] = pos;
  return [
    f * frame.L * WORLD_FRONT[0] + r * frame.W * WORLD_RIGHT[0],
    h * frame.H,
    f * frame.L * WORLD_FRONT[2] + r * frame.W * WORLD_RIGHT[2],
  ];
}

/** A view direction [f, r, h] in the frame → unit world vector (not scaled by the car's proportions). */
export function frameDir(view: Vec3): Vec3 {
  const [f, r, h] = view;
  const v: Vec3 = [f * WORLD_FRONT[0] + r * WORLD_RIGHT[0], h, f * WORLD_FRONT[2] + r * WORLD_RIGHT[2]];
  const n = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / n, v[1] / n, v[2] / n];
}

export type CameraPose = { eye: Vec3; target: Vec3 };

/** Overview: front-left three-quarter, slightly elevated. */
export const OVERVIEW = { target: [0, 0, 0.42] as Vec3, view: [0.85, -0.95, 0.42] as Vec3, dist: 2.75 };

export function poseFor(zone: Pick<ZoneDef, "pos" | "view" | "dist"> | null, frame: CarFrame): CameraPose {
  const z = zone ?? { pos: OVERVIEW.target, view: OVERVIEW.view, dist: OVERVIEW.dist };
  const target = zoneToWorld(z.pos, frame);
  const d = frameDir(z.view);
  const k = z.dist * frame.L;
  return { target, eye: [target[0] + d[0] * k, target[1] + d[1] * k, target[2] + d[2] * k] };
}

/** Zones whose focus turns the body into x-ray. */
export const INTERIOR_ZONES = new Set(["cockpit", "front_seats", "cabin", "rear_seats"]);
// Page 3's stages in the shared canvas, continuing the Evidence → Structure morph as one object story:
// areas: the requirement-area diamonds rise from their Structure ring (exact page-2 spots) to a plane above the
//        volume, which sinks away below them;
// drafted: each diamond bursts into its requirements (domain hue, track-state mark), which settle into one group per
//        vehicle domain; emptied diamonds fade;
// specified: every requirement shows its recommended target, "?" where a gap is open;
// linked: the couplings run as arcs between the requirements on the plane;
// car: today's car rises (DefinitionLayer) and every requirement flies down to its zone, where the pins take over.
// Every move is a scalar that runs toward its goal, so stepping back plays the same move in reverse.
import { createContext, memo, useCallback, useContext, useEffect, useMemo, useRef, type MutableRefObject } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import { Html, Line } from "@react-three/drei";
import { useQuery } from "@tanstack/react-query";
import * as THREE from "three";
import { api } from "@/lib/api";
import { useCheckpoint } from "@/state/checkpoint";
import type { AreaNode, StructurePayload } from "@/lib/types";
import type { DefinitionPayload, DefLink, Requirement } from "@/lib/definition";
import { zoneToWorld, type CarFrame, type Vec3 } from "@/three/frame";
import { AREA_Y, areaLayout } from "../structure/StructureLayer";
import { domainColor, fmtLevel, isDashed, linkVerdict, rowFor } from "./data";
import { select, setView, useView } from "./store";
import { defAtLeast, type DefStage } from "./stages";

export const RISE_DY = 0.85;                         // how far the diamonds rise above their Structure ring
export const PLANE_Y = AREA_Y + RISE_DY;
const RC = 1.3, SPACING = 0.062;                     // domain groups: ring radius, phyllotaxis step
const RISE_S = 1.2, SPLIT_S = 1.6, LINK_S = 0.6, FLY_S = 1.3, FLY_DELAY = 0.25;
const INK = "#f2f4f7";

const clamp01 = (x: number) => Math.max(0, Math.min(1, x));
const smooth = (a: number, b: number, x: number) => { const t = clamp01((x - a) / (b - a)); return t * t * (3 - 2 * t); };
const easeIO = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const easeOut = (t: number) => 1 - Math.pow(1 - t, 3);
const toward = (v: number, goal: number, step: number) => (goal > v ? Math.min(goal, v + step) : Math.max(goal, v - step));
const hash = (s: string) => { let h = 0; for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0; return Math.abs(h); };
const AREA_COLOR = (a: AreaNode) => (a.kind === "quality" ? "#f5a524" : a.kind === "keep" ? "#eef1f5" : a.kind === "emerging" ? "#d95926" : "#3987e5");

/** One scalar per move; the stage sets the goals. rise: diamonds up · split: diamonds → domain groups ·
 *  link: arcs on the plane · fly: groups → car zones. */
export interface StageAnim { rise: number; split: number; link: number; fly: number; flyWait: number }

type Orbit = { target: THREE.Vector3; update: () => void };

/* ------------------------------------------------------------------------------------------- label collisions */
type Register = (key: string, prio: number) => (el: HTMLElement | null) => void;
const LabelCtx = createContext<Register>(() => () => {});
const FOCUS = 1e9;
function useCollisions(): Register {
  const labels = useRef(new Map<string, { el: HTMLElement; prio: number }>());
  const tick = useRef(0);
  const register = useCallback<Register>((key, prio) => (el) => {
    if (el) labels.current.set(key, { el, prio }); else labels.current.delete(key);
  }, []);
  useFrame(() => {
    if (tick.current++ % 6) return;
    const placed: DOMRect[] = [];
    for (const { el, prio } of [...labels.current.values()].sort((a, b) => b.prio - a.prio)) {
      const r = el.getBoundingClientRect();
      if (!r.width) continue;
      const hit = prio < FOCUS && placed.some((q) => r.left < q.right + 3 && r.right > q.left - 3 && r.top < q.bottom + 2 && r.bottom > q.top - 2);
      el.toggleAttribute("data-collide", hit);
      if (!hit) placed.push(r);
    }
  });
  return register;
}

/* ------------------------------------------------------------------------------------------- layer */
interface Props {
  active: boolean;                       // page 3 is showing
  data: DefinitionPayload;
  reqs: Requirement[];                   // on the chosen car line
  line: string;
  frame: CarFrame;
  carScale: number;
  spread: number;                        // the scan's layout scale (the diamonds start where page 2 drew them)
  anim: MutableRefObject<StageAnim>;
  onLanded: (landed: boolean) => void;
  reduced: boolean;

