// Page 3's stage funnel and stepper, built like page 2's (same classes, same [ and ] keys): areas → requirements →
// specified → links → on the car. Arriving on the page plays the stages once (skippable; under reduced motion it
// lands on the last stage); after that the PM steps. The 3D side reads the stage from the store (StageLayer).
import { useEffect, useMemo, useRef } from "react";
import { useQuery } from "@tanstack/react-query";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { api } from "@/lib/api";
import type { StructurePayload } from "@/lib/types";
import { useCheckpoint } from "@/state/checkpoint";
import { StateMark } from "../structure/panels";
import { linkVerdict, type DefData } from "./data";
import { setView, useView } from "./store";
import { DEF_STAGE_LABEL, defAtLeast, defDoneStages, type DefStage } from "./stages";

const fmt = (n: number | undefined | null) => (n == null ? "–" : n.toLocaleString("en-US"));

const STEP_NOTE: Record<DefStage, string> = {
  areas: "Requirement areas from Structure, lifted out of the evidence",
  drafted: "Each area split into requirements, grouped by vehicle domain",
  specified: "Each requirement gets a measurable target; ? marks an open gap",
  linked: "Requirements that help or compete with each other",
  car: "Every requirement where the customer feels it on today's car",
};
// how long the arrival play holds each stage before the next (ms): long enough for its move to finish
const HOLD: Record<DefStage, number> = { areas: 1900, drafted: 2600, specified: 1900, linked: 2100, car: 0 };

export function useStructure() {
  const { cp } = useCheckpoint();
  return useQuery({ queryKey: ["structure", cp], queryFn: () => api.get<StructurePayload>(`/api/structure?cp=${cp}`),
                    staleTime: 30_000, placeholderData: (prev) => prev });
}

export function DefinitionFunnel({ def }: { def: DefData }) {
  const { position } = useCheckpoint();
  const structure = useStructure().data;
  const st = structure?.ready ? structure : undefined;
  const line = useView((s) => s.line);
  const stored = useView((s) => s.stage);
  const auto = useView((s) => s.auto);
  useView((s) => s.pendingLinks);
  const doneKey = defDoneStages(def, !!st).join(",");
  // keyed by its contents: a refetch of the same payload must not restart the arrival play's timer
  const done = useMemo(() => (doneKey ? doneKey.split(",") as DefStage[] : []), [doneKey]);
  const stage: DefStage = done.includes(stored) ? stored : done[done.length - 1] ?? "car";
  const doneRef = useRef(done);
  doneRef.current = done;
  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);

  // keep the store on a stage this checkpoint has
  useEffect(() => { if (done.length && stored !== stage) setView({ stage }); }, [done, stored, stage]);

  // arrival: play the stages once from the areas (or land on the last one under reduced motion)
  const ready = done.length > 0;
  useEffect(() => {
    if (!ready) return;
    const ds = doneRef.current;
    if (reduced || ds.length < 2) setView({ stage: ds[ds.length - 1], auto: false });
    else setView({ stage: ds[0], auto: true });
    return () => setView({ auto: false, hoverArea: null, hoverDomain: null });
  }, [ready, reduced]);
  useEffect(() => {
    if (!auto) return;
    const i = done.indexOf(stage);
    if (i < 0 || i >= done.length - 1) { setView({ auto: false }); return; }
    const t = window.setTimeout(() => setView({ stage: done[i + 1], auto: i + 1 < done.length - 1 }), HOLD[stage]);
    return () => window.clearTimeout(t);
  }, [auto, stage, done]);

  const go = (s: DefStage) => setView({ stage: s, auto: false });
  const step = (d: -1 | 1) => { const i = done.indexOf(stage) + d; if (i >= 0 && i < done.length) go(done[i]); else setView({ auto: false }); };
  // [ and ] step back and forward on page 3 too (the arrow keys belong to the checkpoints)
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.metaKey || e.ctrlKey || e.altKey || (e.target instanceof HTMLElement && /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName) && (e.target as HTMLInputElement).type !== "range")) return;
      if (e.key === "[") step(-1);
      if (e.key === "]") step(1);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  });

  /* the numbers */
  const reqs = def.data.requirements.filter((r) => r.lines.includes(line));
  const keys = new Set(reqs.map((r) => r.key));
  const rows = reqs.flatMap((r) => r.ladder.filter((x) => x.line === line));
  const levels = rows.flatMap((x) => [x.baseline, x.threshold, x.target, x.stretch]);
  const gaps = levels.filter((l) => l?.basis === "gap").length;
  const cited = levels.filter((l) => l?.basis === "cited").length;
  const links = def.data.links.filter((l) => keys.has(l.a) && keys.has(l.b) && linkVerdict(l) !== "removed");
  const bundles = def.data.bundles.filter((b) => b.keys.some((k) => keys.has(k))).length;
  const placed = reqs.filter((r) => r.zones.some((z) => def.data.zones[z]));
  const zones = new Set(placed.map((r) => r.zones.find((z) => def.data.zones[z]))).size;
  const later = position > 1;
  const nu = (xs: { state: string | null }[]) => (later ? xs.filter((x) => x.state === "new").length : 0);
  const moved = (xs: { state: string | null }[]) => (later ? xs.filter((x) => x.state === "changed" || x.state === "strengthened").length : 0);
  const cells: { stage: DefStage; label: string; n: number | undefined; nu?: number; ch?: number; note?: string[] }[] = [
    { stage: "areas", label: "Areas", n: st ? st.areas.filter((a) => a.kind !== "quality").length : undefined },
    { stage: "drafted", label: "Requirements", n: reqs.length, nu: nu(reqs) },
    { stage: "specified", label: "Specified", n: reqs.filter((r) => r.ladder.some((x) => x.line === line)).length, ch: moved(reqs),
      note: [`${fmt(gaps)} gaps`, `${fmt(cited)} cited`] },
    { stage: "linked", label: "Links", n: links.length, nu: nu(links), note: [`${fmt(bundles)} bundles`] },
    { stage: "car", label: "On the car", n: placed.length, note: [`${fmt(zones)} zones`] },
  ];
  const at = done.indexOf(stage);

  return (
    <div className="funnel-wrap dfunnel">
      <dl className="funnel" aria-label="How the requirement areas became requirements on the car">
        {cells.map((c, i) => (
          <div key={c.stage} className="funnel-cell" data-ahead={!defAtLeast(stage, c.stage) ? "" : undefined} data-current={c.stage === stage ? "" : undefined}>
            <dt className="label">
              <button type="button" className="funnel-pick" disabled={!done.includes(c.stage)} aria-pressed={c.stage === stage}
                      onClick={() => go(c.stage)} title={`Show the requirements after ${DEF_STAGE_LABEL[c.stage]}`}>{c.label}</button>
            </dt>
            <dd>
              <span className="num">{done.includes(c.stage) ? fmt(c.n) : "–"}</span>
              {((c.nu ?? 0) > 0 || (c.ch ?? 0) > 0) && (
                <span className="funnel-delta">
                  {(c.nu ?? 0) > 0 && <span><StateMark state="new" />{c.nu}</span>}
                  {(c.ch ?? 0) > 0 && <span><StateMark state="strengthened" />{c.ch}</span>}
                </span>
              )}
            </dd>
            {c.note && done.includes(c.stage) && <dd className="dfunnel-note">{c.note.map((t) => <span key={t}>{t}</span>)}</dd>}
            {i < cells.length - 1 && <svg className="funnel-arrow" width="18" height="10" viewBox="0 0 18 10" aria-hidden><path d="M0 5h15M11 1l4 4-4 4" fill="none" stroke="currentColor" /></svg>}
          </div>
        ))}
      </dl>
      <div className="funnel-step" role="group" aria-label="Step through the stages">
        <button type="button" onClick={() => step(-1)} disabled={at <= 0} aria-label="Previous stage" title="Previous stage ([)"><ChevronLeft size={14} /></button>
        <span className="funnel-step-n num">{at + 1}/{done.length}</span>
        <button type="button" onClick={() => step(1)} disabled={at >= done.length - 1} aria-label="Next stage" title="Next stage (])"><ChevronRight size={14} /></button>
        <span className="funnel-step-name">{DEF_STAGE_LABEL[stage]}</span>
        <span className="funnel-step-note" aria-live="polite">{STEP_NOTE[stage]}</span>
        {auto && <button type="button" className="dfunnel-skip" onClick={() => go(done[done.length - 1])}>Skip</button>}
      </div>
      <AreaHover def={def} structure={st} />
    </div>
  );
}

/** Hovering a diamond on the Areas stage: its title and what it became. */
function AreaHover({ def, structure }: { def: DefData; structure: StructurePayload | undefined }) {
  const key = useView((s) => s.hoverArea);
  const pos = useView((s) => s.hoverPos);
  const line = useView((s) => s.line);
  if (!key || !pos || !structure) return null;
  const a = structure.areas.find((x) => x.key === key);
  if (!a) return null;
  const kids = def.data.requirements.filter((r) => r.area_key === key && r.lines.includes(line));
  const left = Math.min(pos.x + 16, window.innerWidth - 336), top = Math.min(pos.y + 16, window.innerHeight - 160);
  return (
    <div className="hovercard" style={{ left, top }} role="tooltip">
      <p>{a.title}</p>
      <div className="hovercard-meta">
        <span>{a.kind === "quality" ? "Quality hand-over" : `Requirement area · ${a.kind}`}</span>
        <span>{kids.length ? `→ ${kids.length} requirement${kids.length > 1 ? "s" : ""}` : "no requirement drafted"}</span>
      </div>
    </div>
  );
}

// Page 3 overlays at the edges of the shared canvas: readout, car-line switch, domain filter and the requirement list
// top-left; the requirement inspector (metric, acceptance, target ladders, links) top-right; the hover card; and the
// Guide dock bottom-left. All state lives in ./store so the 3D layer and the overlays stay in step.
import { useEffect, useMemo, useRef, useState } from "react";
import { useProgress } from "@react-three/drei";
import { ArrowRight, ChevronsLeft, ChevronsRight, SlidersHorizontal, X } from "lucide-react";
import { useLocation, useNavigate } from "react-router-dom";
import type { DefLink, Requirement } from "@/lib/definition";
import { Dock } from "@/components/Guide";
import { AgentPanel, useActivity } from "../structure/AgentPanel";
import { getTopPanel, setTopPanel, useTopPanel } from "@/components/topPanel";
import {
  LINES, RELATION_NAME, domainColor, fmtLevel, isDashed, linkVerdict, rowFor, useChoice, useDefinition, useLinkReview,
  useRequirementDetail, type DefData,
} from "./data";
import { Ladder } from "./Ladder";
import { DefinitionGuide } from "./guide";
import { getView, select, setView, useView, type LinkMode } from "./store";
import { DefinitionFunnel } from "./DefinitionFunnel";
import "./definition.css";

export function DefinitionHud() {
  const def = useDefinition();
  const activity = useActivity("definition");
  const line = useView((s) => s.line);
  const selected = useView((s) => s.selected);
  const domains = useView((s) => s.domains);
  const linkMode = useView((s) => s.links);
  useView((s) => s.pendingLinks);
  const { data } = def;

  const onLine = useMemo(() => data.requirements.filter((r) => r.lines.includes(line)), [data, line]);
  const sel = selected ? data.requirements.find((r) => r.key === selected) ?? null : null;

  // the list and inspector sit behind the Requirements pill, top-right next to Audit; one of the two is open at a time.
  // Picking a requirement (a pin or a row) opens the panel; closing it, or opening Audit, deselects so the car recentres.
  const top = useTopPanel();
  const showReq = top === "requirements";
  useEffect(() => { if (selected && getTopPanel() !== "requirements") setTopPanel("requirements"); }, [selected]);
  useEffect(() => { if (top !== "requirements" && getView().selected) select(null); }, [top]);

  // a requirement that is not on the chosen line closes; Esc closes the inspector, then clears filters, then the panel
  useEffect(() => { if (sel && !sel.lines.includes(line)) select(null); }, [sel, line]);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      const v = getView();
      if (v.selected) select(null);
      else if (v.domains.length || v.bundle) setView({ domains: [], bundle: null });
      else setTopPanel((t) => (t === "requirements" ? null : t));
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);
  useEffect(() => () => setView({ hover: null, hoverPos: null }), []);

  const counts = useMemo(() => {
    const c: Record<string, number> = {};
    for (const r of onLine) c[r.domain] = (c[r.domain] ?? 0) + 1;
    return c;
  }, [onLine]);
  const toggleDomain = (d: string) => setView((s) => ({ domains: s.domains.includes(d) ? s.domains.filter((x) => x !== d) : [...s.domains, d] }));

  return (
    <>
      <div className="hud-tl dhud">
        {/* the stage funnel replaces the readout: the same counts, as the steps that produced them */}
        <DefinitionFunnel def={def} />
        {def.sample && (
          <p className="dsample" role="status"><b>Sample data</b> {def.why}. Live definitions replace it as soon as the pipeline has run.</p>
        )}
        <div className="dcontrols">
          <div className="dseg" role="radiogroup" aria-label="Car line">
            {LINES.map((l) => (
              <button key={l} role="radio" aria-checked={line === l} onClick={() => setView({ line: l })}>{l}</button>
            ))}
          </div>
          <div className="dseg" role="radiogroup" aria-label="Links">
            <span className="dseg-name label">Links</span>
            {(["strong", "all", "off"] as LinkMode[]).map((m) => (
              <button key={m} role="radio" aria-checked={linkMode === m} onClick={() => setView({ links: m })}>{m === "strong" ? "Strong" : m === "all" ? "All" : "Off"}</button>
            ))}
          </div>
          {/* one line: car line, links, then the domain filter */}
          <DomainFilter data={data} counts={counts} domains={domains} onToggle={toggleDomain} />
        </div>

        <ModelProgress />
      </div>

      {showReq && (sel ? <Inspector key={sel.key} def={def} r={sel} line={line} /> : <RequirementList def={def} reqs={onLine} line={line} />)}
      <PinHover def={def} />
      <Dock mode="definition" sel={null} guide={<DefinitionGuide sel={sel} />} agent={<AgentPanel layer="definition" />} running={!!activity.data?.running} />
    </>
  );
}

// Domain chips, organised like the Evidence filter bar: a toggle at the head of the row folds the unused domains away
// and unfolds them again (kept per browser); chosen domains always stay, first, in the order they were chosen, so
// folding never hides an active filter and choosing one never moves a chip that is already set.
const DOMAIN_FOLD_KEY = "definition.domains.folded";
const readDomainFold = () => { try { return localStorage.getItem(DOMAIN_FOLD_KEY) === "1"; } catch { return false; } };

function DomainFilter({ data, counts, domains, onToggle }: {
  data: DefData["data"]; counts: Record<string, number>; domains: string[]; onToggle: (d: string) => void;
}) {
  const [folded, setFolded] = useState(readDomainFold);
  const fold = (f: boolean) => {
    setFolded(f);
    try { localStorage.setItem(DOMAIN_FOLD_KEY, f ? "1" : "0"); } catch { /* storage blocked: the choice just isn't kept */ }
  };
  const byKey = new Map(data.domains.map((d) => [d.key, d]));
  const active = domains.filter((k) => byKey.has(k));
  const idle = data.domains.filter((d) => counts[d.key] && !domains.includes(d.key)).map((d) => d.key);
  return (
    <div className="dfilters" role="toolbar" aria-label="Filter by domain" data-folded={folded ? "" : undefined}>
      <button className="dfilters-fold" aria-expanded={!folded} aria-controls="definition-domain-chips"
              aria-label={folded ? "Show all domains" : "Hide unused domains"} title={folded ? "Show all domains" : "Hide unused domains"}
              onClick={() => fold(!folded)}>
        <SlidersHorizontal size={12} aria-hidden />
        {folded && <span>Domains{idle.length ? ` · ${idle.length}` : ""}</span>}
        {folded ? <ChevronsRight size={13} aria-hidden /> : <ChevronsLeft size={13} aria-hidden />}
      </button>
      {/* one line: chips that don't fit scroll sideways; a plain mouse wheel scrolls them too */}
      <div className="dchips" id="definition-domain-chips"
           onWheel={(e) => { if (Math.abs(e.deltaY) > Math.abs(e.deltaX)) e.currentTarget.scrollLeft += e.deltaY; }}>
        {[...active, ...(folded ? [] : idle)].map((k) => {
          const d = byKey.get(k)!;
          return (
            <button key={k} className="dchip" aria-pressed={domains.includes(k)} onClick={() => onToggle(k)}>
              <i style={{ background: domainColor(k) }} aria-hidden />{d.label}<span>{counts[k] ?? 0}</span>
            </button>
          );
        })}
        {active.length > 0 && <button className="filters-clear" onClick={() => setView({ domains: [] })}>Clear <span className="label">Esc</span></button>}
      </div>
    </div>
  );
}

