function ModelProgress() {
  const { active, progress } = useProgress();
  if (!active) return null;
  return <p className="dprogress label" role="status">Loading the car · {Math.round(progress)}%</p>;
}

/* --------------------------------------------------------------------------------------------- list */
function RequirementList({ def, reqs, line }: { def: DefData; reqs: Requirement[]; line: string }) {
  const selected = useView((s) => s.selected);
  const domains = useView((s) => s.domains);
  const groups = def.data.domains
    .map((d) => ({ d, items: reqs.filter((r) => r.domain === d.key && (!domains.length || domains.includes(r.domain))) }))
    .filter((g) => g.items.length);
  return (
    <nav className="dlist" id="requirements-panel" aria-label="Requirements">
      <p className="dlist-head"><span className="sheet-layer">Requirements · {line}</span><span className="label">Recommended target</span></p>
      {groups.map(({ d, items }) => (
        <section key={d.key}>
          <h3 className="dlist-domain"><i style={{ background: domainColor(d.key) }} aria-hidden />{d.label}<span>{items.length}</span></h3>
          <ul>
            {items.map((r) => {
              const row = rowFor(r, line);
              const lvl = row ? row[row.recommended] : null;
              return (
                <li key={r.key}>
                  <button className="dlist-row" aria-current={selected === r.key ? "true" : undefined}
                          onClick={() => select(selected === r.key ? null : r.key)}
                          onPointerEnter={() => setView({ hover: r.key })} onPointerLeave={() => setView({ hover: null })}>
                    <PinMark r={r} />
                    <span className="dlist-title">{r.title}</span>
                    <span className="dlist-val">{lvl ? (lvl.basis === "gap" ? "?" : fmtLevel(lvl.value, r.metric?.unit)) : ""}</span>
                  </button>
                </li>
              );
            })}
          </ul>
        </section>
      ))}
    </nav>
  );
}

export function PinMark({ r }: { r: Pick<Requirement, "domain" | "state"> }) {
  return <i className="dmark" data-state={r.state ?? "held"} style={{ ["--c" as string]: domainColor(r.domain) }} aria-label={r.state ?? "held"} />;
}

/* --------------------------------------------------------------------------------------------- hover */
function PinHover({ def }: { def: DefData }) {
  const hover = useView((s) => s.hover);
  const pos = useView((s) => s.hoverPos);
  const line = useView((s) => s.line);
  const selected = useView((s) => s.selected);
  if (!hover || !pos || hover === selected) return null;
  const r = def.data.requirements.find((x) => x.key === hover);
  if (!r) return null;
  const row = rowFor(r, line);
  const lvl = row ? row[row.recommended] : null;
  const domain = def.data.domains.find((d) => d.key === r.domain)?.label ?? r.domain;
  const left = Math.min(pos.x + 16, window.innerWidth - 336), top = Math.min(pos.y + 16, window.innerHeight - 140);
  return (
    <div className="hovercard" style={{ left, top }} role="tooltip">
      <p>{r.title}</p>
      <div className="hovercard-meta">
        <PinMark r={r} /><span>{domain}</span>
        {r.metric && lvl && <span>{r.metric.name}: {lvl.basis === "gap" ? "?" : fmtLevel(lvl.value, r.metric.unit)}</span>}
      </div>
      <div className="hovercard-meta"><span>from area · {r.area_title}</span></div>
    </div>
  );
}

/* --------------------------------------------------------------------------------------------- inspector */
function Inspector({ def, r, line }: { def: DefData; r: Requirement; line: string }) {
  const detail = useRequirementDetail(r.key, def);
  const choice = useChoice(def);
  const [allRows, setAllRows] = useState(false);
  const [hot, setHot] = useState<string | null>(null);
  const evRef = useRef<HTMLDivElement>(null);
  const domain = def.data.domains.find((d) => d.key === r.domain)?.label ?? r.domain;
  const evidence = detail?.evidence ?? [];
  const evText = (id: string) => evidence.find((e) => String(e.id) === id)?.text;
  const onSource = (id: string) => {
    setHot(id);
    requestAnimationFrame(() => evRef.current?.querySelector(`[data-ev="${CSS.escape(id)}"]`)?.scrollIntoView({ block: "nearest", behavior: "smooth" }));
  };
  const rows = r.ladder.filter((x) => x.line === line);
  const others = r.ladder.filter((x) => x.line !== line);
  const shown = allRows ? [...rows, ...others] : rows;
  const lines = r.lines.join(", ");

  return (
    <aside className="sheet dsheet" id="requirements-panel" aria-label="Requirement definition">
      <button className="sheet-close" onClick={() => select(null)} aria-label="Close"><X size={16} /></button>
      <header className="sheet-head">
        <span className="sheet-layer"><PinMark r={r} />{domain}</span>
        <p className="sheet-what">A customer requirement with one measurable target. The AI recommends a rung; the PM chooses.</p>
      </header>
      <div className="dsheet-titleblock">
        <h2 className="sheet-title">{r.title}</h2>
        <p className="dsheet-statement">{r.statement}</p>
      </div>
      <FromArea r={r} />
      {r.change_note && <p className="dnote"><span className="label">What changed</span>{r.change_note}</p>}

      {r.metric && (
        <div className="dmetric">
          <span className="label">Metric</span>
          <p className="dmetric-name">{r.metric.name} <span>· {r.metric.unit} · {r.metric.direction === "lower" ? "lower is better" : r.metric.direction === "binary" ? "yes / no" : "higher is better"}</span></p>
          {(r.metric.method || r.metric.conditions) && <p className="dmetric-how">{[r.metric.method, r.metric.conditions].filter(Boolean).join(" · ")}</p>}
        </div>
      )}

      <div className="dblock">
        <span className="label">Target ladder · {line}</span>
        {shown.length === 0 && <p className="use-none">No ladder for {line} yet.</p>}
        {shown.map((row) => (
          <Ladder key={`${row.line}|${row.market}`} reqKey={r.key} row={row} metric={r.metric} evidenceText={evText} onSource={onSource}
                  busy={choice.isPending} sample={def.sample} facts={detail?.facts}
                  onChoose={(level, rationale) => choice.mutate({ key: r.key, line: row.line, market: row.market, level, rationale })} />
        ))}
        {others.length > 0 && (
          <button className="dtext" onClick={() => setAllRows((v) => !v)}>
            {allRows ? "Show only " + line : `Show other lines (${others.map((o) => `${o.line} · ${o.market}`).join(", ")})`}
          </button>
        )}
        {choice.isError && <p className="derror">Not saved: {(choice.error as Error).message}</p>}
      </div>

      {r.acceptance.length > 0 && (
        <div className="dblock">
          <span className="label">Acceptance criteria</span>
          <ul className="daccept">
            {r.acceptance.map((a, i) => (
              <li key={i}><span className="daccept-c">{a.criterion}</span><span className="daccept-pass">{a.pass}</span><span className="daccept-cond">{a.condition}</span></li>
            ))}
          </ul>
        </div>
      )}

      <dl className="sheet-facts">
        {([["Kano", r.kano], ["Horizon", r.horizon_year ? `${r.horizon ?? ""} ${r.horizon_year}`.trim() : r.horizon], ["Today", r.today_status],
           ["Decision", r.decision_type], ["Area", r.area_title], ["Car lines", lines], ["Markets", r.markets.join(", ")],
           ["Evidence", r.evidence_count ? `${r.evidence_count} items` : null]] as [string, string | null][])
          .filter(([, v]) => v).map(([k, v]) => <div key={k}><dt className="label">{k}</dt><dd>{v}</dd></div>)}
      </dl>

      <Links def={def} r={r} />

      {(r.gaps.length > 0 || r.assumptions.length > 0) && (
        <div className="dblock">
          {r.gaps.length > 0 && <><span className="label">Open gaps</span><ul className="drail">{r.gaps.map((g) => <li key={g}>{g}</li>)}</ul></>}
          {r.assumptions.length > 0 && <><span className="label">Assumptions</span><ul className="drail">{r.assumptions.map((g) => <li key={g}>{g}</li>)}</ul></>}
        </div>
      )}

      {evidence.length > 0 && (
        <div className="dblock" ref={evRef}>
          <span className="label">Sources behind the numbers</span>
          <ul className="dev">
            {evidence.map((e) => (
              <li key={String(e.id)} data-ev={String(e.id)} data-hot={hot === String(e.id) ? "" : undefined}>
                <span className="dev-id">{String(e.id)}{e.tier ? ` · ${e.tier}` : ""}{e.published ? ` · ${e.published}` : ""}</span>
                <span className="dev-text">{e.quote ? `“${e.quote}”` : e.text}</span>
                {e.url && <a href={e.url} target="_blank" rel="noreferrer">Open source</a>}
              </li>
            ))}
          </ul>
        </div>
      )}
    </aside>
  );
}

/** Back to page 2 with the area this requirement was drafted from selected (Scan reads ?area=). */
function FromArea({ r }: { r: Requirement }) {
  const navigate = useNavigate();
  const { search } = useLocation();
  const go = () => { const p = new URLSearchParams(search); p.set("area", r.area_key); navigate(`/structure?${p}`); };
  return (
    <div className="bridge dfrom">
      <span>From area</span>
      <button className="bridge-go" onClick={go}>{r.area_title} <ArrowRight size={13} /></button>
    </div>
  );
}

/* --------------------------------------------------------------------------------------------- links */
function Links({ def, r }: { def: DefData; r: Requirement }) {
  const review = useLinkReview(def);
  const bundle = useView((s) => s.bundle);
  useView((s) => s.pendingLinks);
  const [open, setOpen] = useState<{ id: string; verdict: "confirmed" | "removed" } | null>(null);
  const [why, setWhy] = useState("");
  const mine = def.data.links.filter((l) => l.a === r.key || l.b === r.key).sort((a, b) => b.strength - a.strength);
  const byKey = new Map(def.data.requirements.map((x) => [x.key, x]));
  const myBundle = def.data.bundles.find((b) => b.keys.includes(r.key));
  if (!mine.length) return (
    <div className="dblock"><span className="label">Linked requirements</span><p className="use-none">No coupling proposed for this requirement.</p></div>
  );
  const send = (l: DefLink, verdict: "confirmed" | "removed") => {
    if (why.trim().length < 5) return;
    review.mutate({ link: l, a: l.a, b: l.b, relation: l.relation, verdict, via: String(l.via), strength: l.strength, rationale: why.trim() });
    setOpen(null); setWhy("");
  };
  return (
    <div className="dblock">
      <div className="dlinks-head">
        <span className="label">Linked requirements</span>
        {myBundle && (
          <button className="dtext" aria-pressed={bundle === myBundle.id} onClick={() => setView({ bundle: bundle === myBundle.id ? null : myBundle.id })}>
            {bundle === myBundle.id ? "Hide bundle" : `Show bundle · ${myBundle.keys.length}`}
          </button>
        )}
      </div>
      <ul className="dlinks">
        {mine.map((l) => {
          const other = byKey.get(l.a === r.key ? l.b : l.a);
          const verdict = linkVerdict(l);
          const out = l.relation === "enables" ? ((l.a === r.key) === (l.direction !== "b_to_a") ? "enables" : "enabled by") : RELATION_NAME[l.relation].toLowerCase();
          const id = String(l.id);
          return (
            <li key={id} data-removed={verdict === "removed" ? "" : undefined}>
              <div className="dlink-top">
                <span className="use-rel dlink-rel" data-dashed={isDashed(l.relation) ? "" : undefined}>{out}</span>
                <span className="dlink-via">via {l.via}</span>
                <span className="dlink-str" aria-label={`strength ${l.strength} of 3`}>{[1, 2, 3].map((i) => <i key={i} data-on={i <= l.strength ? "" : undefined} />)}</span>
                {l.state === "new" && <span className="dlink-new label">new</span>}
              </div>
              {other ? (
                <button className="dlink-other" onClick={() => select(other.key)}><PinMark r={other} />{other.title}</button>
              ) : <span className="dlink-other">{l.a === r.key ? l.b : l.a}</span>}
              <p className="use-why">{l.rationale}</p>
              {verdict === "confirmed" || verdict === "removed" ? (
                <p className="dlink-review label">{verdict === "confirmed" ? "Confirmed" : "Removed"} by {l.review?.actor ?? "PM"}{l.review?.rationale ? ` · ${l.review.rationale}` : ""}</p>
              ) : open?.id === id ? (
                <form className="ladder-choose" onSubmit={(e) => { e.preventDefault(); send(l, open.verdict); }}>
                  <textarea rows={2} value={why} onChange={(e) => setWhy(e.target.value)} autoFocus
                            placeholder={`Why ${open.verdict === "confirmed" ? "confirm" : "remove"} this link? (required)`} aria-label="Rationale" />
                  <div className="ladder-actions">
                    <button type="submit" className="dbtn primary" disabled={why.trim().length < 5 || review.isPending}>{open.verdict === "confirmed" ? "Confirm link" : "Remove link"}</button>
                    <button type="button" className="dbtn" onClick={() => { setOpen(null); setWhy(""); }}>Cancel</button>
                  </div>
                </form>
              ) : (
                <div className="dlink-actions">
                  <button className="dtext" onClick={() => { setOpen({ id, verdict: "confirmed" }); setWhy(""); }}>Confirm</button>
                  <button className="dtext" onClick={() => { setOpen({ id, verdict: "removed" }); setWhy(""); }}>Remove</button>
                </div>
              )}
            </li>
          );
        })}
      </ul>
      {review.isError && <p className="derror">Not saved: {(review.error as Error).message}</p>}
      {def.sample && <p className="label">Sample data: reviews are kept in this view only.</p>}
    </div>
  );
}

content.content:
/* Page 3, Definition: the car stage's overlays. Same world as the scan: true black, frameless instruments at the
   24px edge, numerals lead, domain hues on the pins only, white = attention, sweep blue only for the PM's choice. */

/* the scan's DOM labels leave with the volume */
.scan[data-mode="definition"] :is(.ring-name, .ring-sub, .time-label, .ring-label, .theme-label, .area-label) { opacity: 0 !important; pointer-events: none; }

/* ------------------------------------------------------------------------------------------- top-left */
.dhud { gap: 14px; width: 340px; }
.dreadout { margin: 0; display: flex; gap: 26px; pointer-events: none; }
.dreadout div { display: grid; gap: 6px; }
.dreadout dd { margin: 0; display: inline-flex; align-items: baseline; gap: 8px; }
.dreadout .num { font-size: 28px; color: var(--ink); }
.dsample {
  max-width: 320px; font-size: var(--t-label); line-height: 1.45; color: var(--ink-3);
  padding: 6px 10px; border: 1px dashed var(--hair-2); border-radius: 6px; background: rgba(0, 0, 0, 0.6);
}
.dsample b { color: var(--ink); font-weight: 600; letter-spacing: 0.04em; margin-right: 4px; }
.dcontrols { display: flex; flex-wrap: wrap; gap: 8px; }
.dseg { display: inline-flex; align-items: center; height: 28px; padding: 0 2px; border-radius: 99px; border: 1px solid var(--hair); background: rgba(0, 0, 0, 0.6); }
.dseg-name { padding: 0 6px 0 9px; }
.dseg button { height: 22px; padding: 0 10px; border-radius: 99px; font-size: var(--t-label); color: var(--ink-3); transition: color var(--fast), background var(--fast); white-space: nowrap; }
.dseg button:hover { color: var(--ink); }
.dseg button[aria-checked="true"] { color: var(--ink); background: rgba(255, 255, 255, 0.09); }
.dchips { display: flex; flex-wrap: wrap; gap: 6px; }
.dchip {
  display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 10px; border-radius: 99px; border: 1px solid var(--hair);
  background: rgba(0, 0, 0, 0.6); font-size: var(--t-label); color: var(--ink-2); transition: border-color var(--fast), color var(--fast);
}
.dchip i { width: 7px; height: 7px; border-radius: 50%; flex: none; }
.dchip span { color: var(--ink-3); font-variant-numeric: tabular-nums; }
.dchip:hover { border-color: var(--hair-2); color: var(--ink); }
.dchip[aria-pressed="true"] { border-color: rgba(77, 148, 255, 0.55); color: var(--ink); }

/* requirement list: right column while nothing is open (the inspector takes its place); label first, the recommended
   target as the numeral at the right; on the same frameless feathered field as the inspector */
.dlist {
  position: fixed; top: calc(var(--edge) + 46px); right: var(--edge); z-index: 14; width: min(340px, calc(100vw - 32px));
  max-height: calc(100vh - 2 * var(--edge) - 196px); overflow-y: auto; padding: 16px 20px 22px; display: grid; gap: 14px; align-content: start;
  background: var(--field); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  --feather: linear-gradient(to right, transparent, #000 18px, #000 calc(100% - 12px), transparent), linear-gradient(to bottom, transparent, #000 12px, #000 calc(100% - 22px), transparent);
  -webkit-mask-image: var(--feather); mask-image: var(--feather); -webkit-mask-composite: source-in; mask-composite: intersect;
  animation: sheet-in var(--med) var(--ease);
}
.dlist-head { display: flex; justify-content: space-between; align-items: baseline; }
.dlist section { display: grid; gap: 2px; }
.dlist ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px; }
.dlist-domain { display: flex; align-items: center; gap: 7px; margin: 0 0 2px; font-size: var(--t-micro); font-weight: 600; letter-spacing: 0.06em; color: var(--ink-2); }
.dlist-domain i { width: 6px; height: 6px; border-radius: 50%; }
.dlist-domain span { color: var(--ink-3); font-weight: 400; }
.dlist-row {
  width: calc(100% + 16px); display: grid; grid-template-columns: 12px 1fr auto; align-items: center; gap: 10px; padding: 4px 8px; margin-left: -8px;
  border-radius: 6px; text-align: left; transition: background var(--fast);
}
.dlist-row:hover { background: rgba(255, 255, 255, 0.05); }
.dlist-row[aria-current="true"] { background: rgba(255, 255, 255, 0.08); }
.dlist-title { font-size: 13px; color: var(--ink-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dlist-row:hover .dlist-title, .dlist-row[aria-current="true"] .dlist-title { color: var(--ink); }
.dlist-val { font-size: 13px; color: var(--ink); font-stretch: 112%; font-weight: 350; font-variant-numeric: tabular-nums; white-space: nowrap; }
.dprogress { margin-top: -4px; }

/* the pin mark in DOM lists: shape = track state, colour = domain */
.dmark { display: inline-block; width: 10px; height: 10px; border-radius: 50%; flex: none; position: relative; background: var(--c); }
.dmark[data-state="new"] { background: transparent; box-shadow: inset 0 0 0 1.5px var(--c); }
.dmark:is([data-state="changed"], [data-state="strengthened"]) { background: radial-gradient(circle, var(--c) 0 30%, transparent 32%); box-shadow: inset 0 0 0 1.5px var(--c); }
.dmark:is([data-state="weakened"], [data-state="lost"]) { background: var(--lost); }
.dmark[data-state="lost"] { background: transparent; }
.dmark:is([data-state="weakened"], [data-state="lost"])::before, .dmark:is([data-state="weakened"], [data-state="lost"])::after {
  content: ""; position: absolute; left: 4.25px; top: 1px; width: 1.5px; height: 8px; background: #000; transform: rotate(45deg);
}
.dmark[data-state="lost"]::before, .dmark[data-state="lost"]::after { background: var(--lost); }
.dmark:is([data-state="weakened"], [data-state="lost"])::after { transform: rotate(-45deg); }

/* ------------------------------------------------------------------------------------------- pins on the car */
.dzone { display: grid; justify-items: center; gap: 4px; transition: opacity 0.3s var(--ease); user-select: none; }
.dzone[data-behind] { opacity: 0.32; }
.dzone-pins { display: grid; grid-template-columns: repeat(var(--cols, 4), auto); grid-auto-flow: row; justify-content: center; gap: 2px; max-width: 72px; }
.dzone-pins:has(> :only-child) { grid-template-columns: auto; }
.dzone-pins:has(> :nth-child(2):last-child) { grid-template-columns: repeat(2, auto); }
.dzone-pins:has(> :nth-child(3):last-child) { grid-template-columns: repeat(3, auto); }
.dpin { width: 16px; height: 16px; display: grid; place-items: center; border-radius: 50%; position: relative; transition: opacity var(--fast); }
.dpin i { width: 10px; height: 10px; border-radius: 50%; position: relative; background: var(--c); transition: background var(--fast), box-shadow var(--fast); }
.dpin[data-state="new"] i { background: transparent; box-shadow: inset 0 0 0 1.6px var(--c); }
.dpin:is([data-state="changed"], [data-state="strengthened"]) i { width: 12px; height: 12px; background: radial-gradient(circle, var(--c) 0 28%, transparent 30%); box-shadow: inset 0 0 0 1.4px var(--c); }
.dpin:is([data-state="weakened"], [data-state="lost"]) i { --c: var(--lost); }
.dpin:is([data-state="weakened"], [data-state="lost"]) i::before, .dpin:is([data-state="weakened"], [data-state="lost"]) i::after {
  content: ""; position: absolute; left: 4.25px; top: 1px; width: 1.5px; height: 8px; background: #000; transform: rotate(45deg);
}
.dpin:is([data-state="weakened"], [data-state="lost"]) i::after { transform: rotate(-45deg); }
/* white is attention: hovered, linked to the open requirement, or open (with the lock ring) */
.dpin:hover i, .dpin[data-on] i { --c: var(--ink); }
.dpin[data-on]::after { content: ""; position: absolute; inset: -3px; border-radius: 50%; box-shadow: 0 0 0 1px var(--ink); }
.dpin[data-linked]::after { content: ""; position: absolute; inset: -1px; border-radius: 50%; box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.55); }
.dpin[data-dim="dim"] { opacity: 0.3; }
.dpin[data-dim="off"] { opacity: 0.07; pointer-events: none; }
/* new or moved at this checkpoint: one expanding ring when the sweep lands (0ms under reduced motion) */
.dpin[data-pulse]::before { content: ""; position: absolute; inset: 1px; border-radius: 50%; box-shadow: 0 0 0 1.5px var(--ink); opacity: 0; animation: dpin-pulse 1.6s var(--ease) 0.6s 1 both; pointer-events: none; }
@keyframes dpin-pulse { 0% { opacity: 0.95; transform: scale(1); } 100% { opacity: 0; transform: scale(2.8); } }
@media (prefers-reduced-motion: reduce) { .dpin[data-pulse]::before { display: none; } }
.dzone-label {
  display: inline-flex; gap: 5px; align-items: baseline; padding: 1px 5px; border-radius: 4px; background: rgba(0, 0, 0, 0.7);
  font-size: var(--t-micro); letter-spacing: 0.04em; color: var(--ink-2); white-space: nowrap; pointer-events: none;
  opacity: 0; transition: opacity var(--fast);
}
.dzone-label b { font-weight: 600; color: var(--ink); }
.dzone:hover .dzone-label, .dzone[data-focus] .dzone-label { opacity: 1; }

/* the shared resource at a link's apex */
.dlink-label {
  padding: 1px 6px; border-radius: 4px; background: rgba(0, 0, 0, 0.72); font-size: var(--t-micro); font-weight: 600; letter-spacing: 0.08em;
  color: var(--ink); white-space: nowrap; pointer-events: none; user-select: none; box-shadow: inset 0 0 0 1px var(--hair-2);
}
.dlink-label[data-dashed] { box-shadow: none; outline: 1px dashed var(--ink-3); outline-offset: -1px; }

/* ------------------------------------------------------------------------------------------- inspector */
.dsheet { gap: 20px; }
