.dmark[data-state="lost"] { background: transparent; }
.dmark:is([data-state="weakened"], [data-state="lost"])::before, .dmark:is([data-state="weakened"], [data-state="lost"])::after {
  content: ""; position: absolute; left: 4.25px; top: 1px; width: 1.5px; height: 8px; background: #000; transform: rotate(45deg);
}
.dmark[data-state="lost"]::before, .dmark[data-state="lost"]::after { background: var(--lost); }
.dmark:is([data-state="weakened"], [data-state="lost"])::after { transform: rotate(-45deg); }

/* ------------------------------------------------------------------------------------------- pins on the car */
.dzone { display: grid; justify-items: center; gap: 4px; transition: opacity 0.3s var(--ease); user-select: none; }
.dzone[data-behind] { opacity: 0.32; }
.dzone-pins { display: grid; grid-template-columns: repeat(var(--cols, 4), auto); grid-auto-flow: row; justify-content: center; gap: 2px; max-width: 72px; }
.dzone-pins:has(> :only-child) { grid-template-columns: auto; }
.dzone-pins:has(> :nth-child(2):last-child) { grid-template-columns: repeat(2, auto); }
.dzone-pins:has(> :nth-child(3):last-child) { grid-template-columns: repeat(3, auto); }
.dpin { width: 16px; height: 16px; display: grid; place-items: center; border-radius: 50%; position: relative; transition: opacity var(--fast); }
.dpin i { width: 10px; height: 10px; border-radius: 50%; position: relative; background: var(--c); transition: background var(--fast), box-shadow var(--fast); }
.dpin[data-state="new"] i { background: transparent; box-shadow: inset 0 0 0 1.6px var(--c); }
.dpin:is([data-state="changed"], [data-state="strengthened"]) i { width: 12px; height: 12px; background: radial-gradient(circle, var(--c) 0 28%, transparent 30%); box-shadow: inset 0 0 0 1.4px var(--c); }
.dpin:is([data-state="weakened"], [data-state="lost"]) i { --c: var(--lost); }
.dpin:is([data-state="weakened"], [data-state="lost"]) i::before, .dpin:is([data-state="weakened"], [data-state="lost"]) i::after {
  content: ""; position: absolute; left: 4.25px; top: 1px; width: 1.5px; height: 8px; background: #000; transform: rotate(45deg);
}
.dpin:is([data-state="weakened"], [data-state="lost"]) i::after { transform: rotate(-45deg); }
/* white is attention: hovered, linked to the open requirement, or open (with the lock ring) */
.dpin:hover i, .dpin[data-on] i { --c: var(--ink); }
.dpin[data-on]::after { content: ""; position: absolute; inset: -3px; border-radius: 50%; box-shadow: 0 0 0 1px var(--ink); }
.dpin[data-linked]::after { content: ""; position: absolute; inset: -1px; border-radius: 50%; box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.55); }
.dpin[data-dim="dim"] { opacity: 0.3; }
.dpin[data-dim="off"] { opacity: 0.07; pointer-events: none; }
/* new or moved at this checkpoint: one expanding ring when the sweep lands (0ms under reduced motion) */
.dpin[data-pulse]::before { content: ""; position: absolute; inset: 1px; border-radius: 50%; box-shadow: 0 0 0 1.5px var(--ink); opacity: 0; animation: dpin-pulse 1.6s var(--ease) 0.6s 1 both; pointer-events: none; }
@keyframes dpin-pulse { 0% { opacity: 0.95; transform: scale(1); } 100% { opacity: 0; transform: scale(2.8); } }
@media (prefers-reduced-motion: reduce) { .dpin[data-pulse]::before { display: none; } }
.dzone-label {
  display: inline-flex; gap: 5px; align-items: baseline; padding: 1px 5px; border-radius: 4px; background: rgba(0, 0, 0, 0.7);
  font-size: var(--t-micro); letter-spacing: 0.04em; color: var(--ink-2); white-space: nowrap; pointer-events: none;
  opacity: 0; transition: opacity var(--fast);
}
.dzone-label b { font-weight: 600; color: var(--ink); }
.dzone:hover .dzone-label, .dzone[data-focus] .dzone-label { opacity: 1; }

/* the shared resource at a link's apex */
.dlink-label {
  padding: 1px 6px; border-radius: 4px; background: rgba(0, 0, 0, 0.72); font-size: var(--t-micro); font-weight: 600; letter-spacing: 0.08em;
  color: var(--ink); white-space: nowrap; pointer-events: none; user-select: none; box-shadow: inset 0 0 0 1px var(--hair-2);
}
.dlink-label[data-dashed] { box-shadow: none; outline: 1px dashed var(--ink-3); outline-offset: -1px; }

/* ------------------------------------------------------------------------------------------- inspector */
.dsheet { gap: 20px; }
.dsheet .sheet-layer .dmark { margin-right: 2px; }
.dsheet-titleblock { display: grid; gap: 8px; }
.dsheet-statement { font-size: var(--t-body); line-height: 1.5; color: var(--ink-2); max-width: 52ch; }
.dnote { display: grid; gap: 3px; padding: 2px 0 2px 12px; border-left: 1px solid var(--hair-2); font-size: var(--t-label); color: var(--ink-2); line-height: 1.45; }
.dblock { display: grid; gap: 10px; }
.dmetric { display: grid; gap: 4px; }
.dmetric-name { font-size: var(--t-body); color: var(--ink); }
.dmetric-name span { color: var(--ink-3); font-size: var(--t-label); }
.dmetric-how { font-size: var(--t-label); color: var(--ink-3); line-height: 1.45; }
.dtext { justify-self: start; font-size: var(--t-label); color: var(--ink-2); padding: 2px 0; transition: color var(--fast); text-align: left; }
.dtext:hover { color: var(--ink); }
.derror { font-size: var(--t-label); color: var(--lost); }
.drail { list-style: none; margin: 0; padding: 0 0 0 12px; border-left: 1px solid var(--hair-2); display: grid; gap: 4px; font-size: var(--t-label); color: var(--ink-2); line-height: 1.45; }
.daccept { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.daccept li { display: grid; grid-template-columns: 1fr auto; gap: 1px 12px; padding-top: 8px; border-top: 1px solid var(--hair); }
.daccept-c { font-size: 13px; color: var(--ink); }
.daccept-pass { font-size: 13px; color: var(--ink); font-stretch: 112%; text-align: right; }
.daccept-cond { grid-column: 1 / -1; font-size: var(--t-label); color: var(--ink-3); }

/* ladder */
.ladder { display: grid; gap: 8px; padding-top: 10px; border-top: 1px solid var(--hair); }
.ladder-head { display: flex; justify-content: space-between; align-items: baseline; }
.ladder-where { font-size: var(--t-label); font-weight: 600; letter-spacing: 0.04em; color: var(--ink); }
.ladder-scale { position: relative; height: 78px; margin: 0 6px; }
.ladder-rail { position: absolute; left: 0; right: 0; top: 30px; height: 1px; background: var(--hair-2); }
.ladder-rail::after { content: ""; position: absolute; right: -1px; top: -3px; border: 3.5px solid transparent; border-left: 5px solid var(--hair-2); border-right: 0; }
.ladder-rung {
  position: absolute; top: 0; transform: translateX(-50%); display: grid; grid-template-rows: 18px 24px 14px 16px; justify-items: center; align-items: center;
  min-width: 52px; padding: 0 2px; border-radius: 6px; text-align: center;
}
button.ladder-rung { transition: background var(--fast); }
button.ladder-rung:hover { background: rgba(255, 255, 255, 0.05); }
.ladder-val { font-size: 13px; color: var(--ink-2); font-stretch: 112%; font-weight: 350; white-space: nowrap; font-variant-numeric: tabular-nums; }
.ladder-name { font-size: var(--t-micro); color: var(--ink-3); letter-spacing: 0.02em; }
.ladder-tags { display: inline-flex; gap: 3px; }
.ladder-ai, .ladder-pm { font-size: 9.5px; font-weight: 600; letter-spacing: 0.08em; line-height: 13px; padding: 0 3px; border-radius: 3px; color: var(--ink-2); box-shadow: inset 0 0 0 1px var(--hair-2); }
.ladder-pm { color: var(--sweep-hi); box-shadow: inset 0 0 0 1px rgba(77, 148, 255, 0.6); }
.ladder-mark { width: 11px; height: 11px; border-radius: 50%; display: grid; place-items: center; font-style: normal; font-size: 11px; font-weight: 600; line-height: 1; color: var(--ink); background: var(--void); }
.ladder-mark[data-basis="cited"] { background: var(--ink); }
.ladder-mark[data-basis="projected"] { box-shadow: inset 0 0 0 1.5px var(--ink); }
.ladder-mark[data-basis="assumption"] { border: 1.3px dashed var(--ink); }
.ladder-mark[data-basis="gap"] { width: 14px; height: 14px; color: var(--ink-2); box-shadow: inset 0 0 0 1px var(--hair-2); }
.ladder-mark.sm { width: 9px; height: 9px; font-size: 9px; }
.ladder-mark.sm[data-basis="gap"] { width: 11px; height: 11px; }
.ladder-rung[data-rung="baseline"] .ladder-mark { transform: scale(0.8); opacity: 0.7; }
.ladder-rung[data-rung="baseline"] .ladder-val { color: var(--ink-3); }
button.ladder-rung:hover .ladder-val, .ladder-rung[data-on] .ladder-val, .ladder-rung[data-picking] .ladder-val { color: var(--ink); }
/* the PM's chosen rung is the PM's position: sweep blue with its wash halo, like the active checkpoint node */
.ladder-rung[data-on] .ladder-mark { background: var(--sweep-hi); border-color: var(--sweep-hi); box-shadow: 0 0 0 4px var(--sweep-wash); color: var(--void); }
.ladder-rung[data-picking] .ladder-mark { outline: 1px solid var(--ink); outline-offset: 3px; }
.ladder-basis { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; }
.ladder-basis li { display: grid; grid-template-columns: 11px 62px 1fr; align-items: baseline; gap: 8px; font-size: var(--t-label); color: var(--ink-3); line-height: 1.45; }
.ladder-basis .ladder-mark { align-self: center; }
.ladder-basis-k { color: var(--ink-2); }
.ladder-basis-v em { font-style: normal; color: var(--ink-2); }
.ladder-src {
  margin-left: 6px; font-size: var(--t-micro); letter-spacing: 0.04em; color: var(--ink-2); padding: 0 5px; border-radius: 4px; line-height: 16px;
  box-shadow: inset 0 0 0 1px var(--hair-2); transition: color var(--fast), box-shadow var(--fast);
}
.ladder-src:hover { color: var(--ink); box-shadow: inset 0 0 0 1px var(--ink-3); }
.ladder-why { font-size: var(--t-label); color: var(--ink-2); line-height: 1.45; }
.ladder-why .label { margin-right: 6px; }
.ladder-why.pm .label { color: var(--sweep-hi); }
.ladder-choose { display: grid; gap: 8px; padding: 2px 0 2px 12px; border-left: 1px solid var(--hair-2); }
.ladder-choose textarea {
  width: 100%; resize: vertical; min-height: 52px; padding: 8px 10px; border-radius: 6px; border: 1px solid var(--hair-2); background: rgba(0, 0, 0, 0.6);
  color: var(--ink); font: inherit; font-size: 13px; line-height: 1.45;
}
.ladder-choose textarea:focus { outline: none; border-color: var(--sweep-hi); }
.ladder-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
/* rival / benchmark ticks: quiet neutral marks on the rail, secondary to the rungs (never blue, never amber) */
.ladder-scale[data-rivals] { height: 92px; }
.ladder-tick { position: absolute; top: 22px; width: 9px; height: 17px; transform: translateX(-50%); z-index: 2; display: grid; justify-items: center; outline: none; }
.ladder-tick-mark { display: block; width: 1px; height: 11px; margin-top: 3px; background: var(--ink-3); transform-origin: center; transition: background var(--fast), transform var(--fast); }
.ladder-tick-mark.sm { height: 9px; margin: 0 auto; }
.ladder-tick-tag {
  position: absolute; top: 56px; left: 50%; transform: translateX(-50%); white-space: nowrap; pointer-events: none; opacity: 0;
  font-size: var(--t-micro); letter-spacing: 0.02em; color: var(--ink-2); padding: 0 5px; line-height: 16px; border-radius: 4px;
  background: rgba(0, 0, 0, 0.7); box-shadow: inset 0 0 0 1px var(--hair-2); transition: opacity var(--fast);
}
.ladder-tick:hover .ladder-tick-mark, .ladder-tick:focus-visible .ladder-tick-mark { background: var(--ink); transform: scaleY(1.36); }
.ladder-tick:hover .ladder-tick-tag, .ladder-tick:focus-visible .ladder-tick-tag { opacity: 1; }
.ladder-tick:focus-visible { box-shadow: 0 0 0 1px var(--ink-3); border-radius: 2px; }
/* keep the tag inside the sheet at the scale's ends */
.ladder-tick[data-edge="r"] .ladder-tick-tag { left: auto; right: -4px; transform: none; }
.ladder-tick[data-edge="l"] .ladder-tick-tag { left: -4px; transform: none; }
.ladder-rivals { list-style: none; margin: 0; padding: 6px 0 0; border-top: 1px solid var(--hair); display: grid; gap: 3px; }
.ladder-rivals li { display: grid; grid-template-columns: 11px 92px 1fr; align-items: baseline; gap: 8px; font-size: var(--t-micro); color: var(--ink-3); line-height: 1.45; }
.ladder-rivals li[data-off] .ladder-tick-mark { opacity: 0.4; }
.ladder-rivals .ladder-tick-mark { align-self: center; }
.ladder-rivals-k { color: var(--ink-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ladder-rivals-v { font-variant-numeric: tabular-nums; }
.ladder-rivals-v em { font-style: normal; }
.dbtn { height: 28px; padding: 0 12px; border-radius: 99px; border: 1px solid var(--hair); background: rgba(0, 0, 0, 0.6); font-size: var(--t-label); color: var(--ink-2); transition: color var(--fast), border-color var(--fast), background var(--fast); }
.dbtn:hover:not(:disabled) { color: var(--ink); border-color: var(--hair-2); }
.dbtn.primary { color: var(--ink); border-color: var(--hair-2); background: rgba(255, 255, 255, 0.07); }
.dbtn:disabled { opacity: 0.4; cursor: default; }

/* links */
.dlinks-head { display: flex; justify-content: space-between; align-items: baseline; }
.dlinks { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.dlinks li { display: grid; gap: 4px; padding-top: 10px; border-top: 1px solid var(--hair); }
.dlinks li[data-removed] { opacity: 0.55; }
.dlinks li[data-removed] .dlink-other { text-decoration: line-through; text-decoration-color: var(--ink-3); }
.dlink-top { display: flex; align-items: center; gap: 8px; }
.dlink-rel[data-dashed] { color: var(--ink); box-shadow: none; outline: 1px dashed var(--ink-3); outline-offset: -1px; }
.dlink-via { font-size: var(--t-micro); font-weight: 600; letter-spacing: 0.08em; color: var(--ink-2); }
.dlink-str { display: inline-flex; gap: 2px; margin-left: auto; }
.dlink-str i { width: 10px; height: 2px; border-radius: 1px; background: var(--hair-2); }
.dlink-str i[data-on] { background: var(--ink-2); }
.dlink-new { color: var(--ink); }
.dlink-other { display: inline-flex; align-items: center; gap: 8px; font-size: 13px; color: var(--ink); text-align: left; justify-self: start; }
button.dlink-other:hover { text-decoration: underline; text-underline-offset: 3px; text-decoration-color: var(--ink-3); }
.dlink-actions { display: flex; gap: 14px; }
.dlink-review { color: var(--ink-2); }

/* sources behind the numbers */
.dev { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.dev li { display: grid; gap: 2px; padding: 2px 0 2px 12px; border-left: 1px solid var(--hair-2); transition: border-color var(--fast); }
.dev li[data-hot] { border-left-color: var(--ink); }
.dev-id { font-size: var(--t-micro); letter-spacing: 0.04em; color: var(--ink-3); }
.dev li[data-hot] .dev-id { color: var(--ink); }
.dev-text { font-size: var(--t-label); color: var(--ink-2); line-height: 1.45; }
.dev a { font-size: var(--t-label); justify-self: start; }

.dguide-dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; margin-right: 7px; vertical-align: 1px; }

@media (max-width: 760px) {
  .dhud { width: calc(100vw - 32px); }
  .dlist { top: auto; bottom: 140px; max-height: 34vh; }
  .dreadout { gap: 16px; }
  .dreadout .num { font-size: 22px; }
}

/* the guide dock is shorter on page 3 so it clears the domain chips */
.scan[data-mode="definition"] ~ .dock .dock-body, .scan[data-mode="definition"] .dock-body { max-height: min(38vh, 320px); }

/* ------------------------------------------------------------------------------------------- stages (StageLayer) */
/* the stage funnel sits in the top-left column in place of a readout; same markup and classes as page 2's */
.dhud .funnel-wrap.dfunnel { position: static; width: max-content; max-width: calc(100vw - 2 * var(--edge)); }
.funnel-cell dd.dfunnel-note { margin: -4px 0 0; display: grid; gap: 0; font-size: var(--t-micro); color: var(--ink-3); white-space: nowrap; }
.dfunnel .funnel { gap: 12px; }
.dfunnel .funnel-cell { padding-right: 28px; }
.dfunnel .funnel-cell .num { font-size: 28px; }   /* the readout size: five stages must clear the page switch */
.dfunnel .funnel-arrow { top: 26px; }
.dfunnel .funnel-cell:last-child { padding-right: 0; }
.dfunnel-skip {
  height: 24px; padding: 0 10px; border-radius: 99px; border: 1px solid var(--hair); background: rgba(0, 0, 0, 0.6);
  font-size: var(--t-label); color: var(--ink-2); transition: color var(--fast), border-color var(--fast);
}
.dfunnel-skip:hover { color: var(--ink); border-color: var(--hair-2); }

/* area diamonds lifted onto the plane: page 2's area label, plus how many requirements it holds */
.dstage-area {
  display: inline-flex; gap: 6px; align-items: baseline; padding: 2px 7px; border-radius: 5px; background: rgba(0, 0, 0, 0.65);
  font-size: var(--t-micro); font-weight: 500; color: var(--ink-2); white-space: nowrap; pointer-events: none; user-select: none;
}
.dstage-area b { font-weight: 600; color: var(--ink); }
.dstage-area[data-collide] { visibility: hidden; }

/* requirement nodes on the plane: the car's pin mark, grown out of its diamond (--s), target to the right */
.dnode { position: relative; display: grid; place-items: center; transform: scale(var(--s, 1)); }
.dnode-val {
  position: absolute; left: 17px; top: 50%; transform: translateY(-50%); display: inline-flex; gap: 3px; align-items: baseline;
  padding: 0 4px; border-radius: 3px; background: rgba(0, 0, 0, 0.62); font-size: var(--t-micro); font-variation-settings: "wdth" 112;
  color: var(--ink-2); white-space: nowrap; pointer-events: none; user-select: none; animation: dnode-in var(--med) var(--ease);
  opacity: var(--v, 1);
}
.dnode-val b { font-weight: 600; color: var(--ink-3); }
.dnode-val[data-collide] { visibility: hidden; }
.dnode-val[data-dim="dim"] { opacity: 0.3; }
.dnode-val[data-dim="off"] { display: none; }
.dnode:hover .dnode-val, .dnode:has(.dpin[data-on]) .dnode-val { visibility: visible; color: var(--ink); z-index: 1; }
@keyframes dnode-in { from { opacity: 0; } to { opacity: 1; } }

/* a domain group's name and count, outside its disc; hover lights the group, click filters like the chips */
.dgroup {
  display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 8px; border-radius: 99px; border: 1px solid transparent;
  background: rgba(0, 0, 0, 0.66); font-size: var(--t-micro); letter-spacing: 0.02em; color: var(--ink-2); white-space: nowrap;
  transition: color var(--fast), border-color var(--fast);
}
.dgroup i { width: 6px; height: 6px; border-radius: 50%; background: var(--c); }
.dgroup b { font-weight: 600; color: var(--ink); }
.dgroup:hover { color: var(--ink); border-color: var(--hair-2); }
.dgroup[data-on] { color: var(--ink); border-color: var(--sweep-hi); }

/* pins take over from the flying nodes when they land */
.dzone { animation: dnode-in var(--fast) var(--ease); }   /* no fill: [data-behind] keeps its 32% */

/* the inspector's way back to the area on Structure */
.dsheet .dfrom { padding-top: 0; border-top: 0; }
@media (prefers-reduced-motion: reduce) { .dnode-val, .dzone { animation: none; } }

/* car line, links and the domain filter on one line (the HUD itself stays 340px; this row may run wider). The domain
   chips stay on that line and scroll sideways when they don't fit, fading out at the edge; folding hides the unused ones. */
.dhud .dcontrols { flex-wrap: nowrap; align-items: center; width: max-content; max-width: calc(100vw - 2 * var(--edge) - 440px); }
.dhud .dcontrols > .dseg { flex: none; }
.dfilters { display: flex; align-items: center; gap: 6px; min-width: 0; }
.dfilters .dchips { flex-wrap: nowrap; min-height: 28px; min-width: 0; align-items: center; overflow-x: auto; scrollbar-width: none;
  -webkit-mask-image: linear-gradient(to right, #000 calc(100% - 28px), transparent); mask-image: linear-gradient(to right, #000 calc(100% - 28px), transparent); padding-right: 22px; }
.dfilters .dchips::-webkit-scrollbar { display: none; }
.dfilters .dchip, .dfilters .filters-clear { flex: none; white-space: nowrap; }
.dfilters-fold { flex: none; display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 9px; border-radius: 99px; border: 1px solid transparent; font-size: var(--t-label); color: var(--ink-3); transition: color var(--fast), border-color var(--fast), background var(--fast); }
.dfilters-fold:hover { color: var(--ink); border-color: var(--hair); background: rgba(255, 255, 255, 0.04); }
.dfilters[data-folded] .dfilters-fold { color: var(--ink-2); }
.dfilters[data-folded] .dchips { -webkit-mask-image: none; mask-image: none; padding-right: 0; }
@media (max-width: 760px) { .dhud .dcontrols { flex-wrap: wrap; max-width: none; width: auto; } .dfilters .dchips { flex-wrap: wrap; overflow: visible; -webkit-mask-image: none; mask-image: none; } }

content.content:
// Audit, top-right. Opens on what the current page is about, for the selected checkpoint only: on Evidence, what
// entered the data and when; on Structure, when the agent ran each stage and every AI step. "Everything" shows both
// checkpoints, each row tagged; history from before the checkpoint rebuild (the old wave-based app) is kept in the
// append-only trail but only shown there on request. Styled like the rest of the HUD: a 28px pill like the filter chips, a glass sheet like the
// inspector. Inside, the trail runs down one hairline rail: stage runs are milestones, every other row is a step.
// Identical steps of one stream (same action, stage and checkpoint, no gap over 10 minutes; the agent classifies 20
// comments per call) fold into one row with their totals and can be opened, even when another run's steps interleave. Chips on top show or hide who acted.
import { useEffect, useMemo, useState } from "react";
import { useInfiniteQuery } from "@tanstack/react-query";
import { useLocation } from "react-router-dom";
import { ChevronRight, History, ListChecks, X } from "lucide-react";
import { api } from "@/lib/api";
import { useCheckpoint } from "@/state/checkpoint";
import { line } from "@/screens/structure/AgentPanel";
import { setTopPanel, toggleTopPanel, useTopPanel } from "./topPanel";
import { UsageView } from "./Usage";
import "./audit.css";

interface Row {
  id: string; ts: string; actor_type: "ai" | "system" | "human"; actor: string; model: string | null;
  kind: string; stage: string | null; action: string; payload: Record<string, unknown>; checkpoint: string | null; summary: string | null;
}
