.pmatrix-prop { position: absolute; right: 2px; top: 1px; font-size: 8.5px; font-weight: 600; color: var(--ink); letter-spacing: 0.04em; }
.pmatrix-dis { width: 2px; height: 14px; justify-self: center; border-radius: 1px; }
.pmatrix-dis[data-on], .pmatrix-legend .pmatrix-dis { background: var(--ink); }
.pmatrix-legend .pmatrix-dis { display: inline-block; height: 10px; }

@media (max-width: 1100px) { .pmatrix { width: calc(100vw - 2 * var(--edge)); } }
@media (max-width: 760px) {
  .phud { max-width: calc(100vw - 32px); }
  .preadout { gap: 14px; flex-wrap: wrap; }
  .preadout-band .num { font-size: 24px; }
  .pmatrix { left: 16px; right: 16px; width: auto; top: 220px; }
}

